public int compare(final Object value1, final byte type1, final Object value2, final byte type2) {
    if (value1 == null) {
      if (value2 == null)
        return 0;
      else
        return -1;
    } else if (value2 == null)
      return 1;

    switch (type1) {
    case BinaryTypes.TYPE_INT:
    case BinaryTypes.TYPE_SHORT:
    case BinaryTypes.TYPE_BYTE:
      // Always widen the other operand to its own natural width instead of narrowing it to type1's width:
      // narrowing a wider or floating operand (e.g. a `long` outside `int` range via intValue(), or a fractional
      // `double` via intValue()) can silently truncate it onto the wrong side of value1, which breaks the
      // antisymmetry every comparator must honour (issue #5900).
      return compareNarrowIntegral((Number) value1, type2, value2);

    case BinaryTypes.TYPE_LONG:
      // Same rationale as the INT/SHORT/BYTE case above: a fractional DECIMAL/FLOAT/DOUBLE narrowed via
      // longValue() drops its fraction and can land on the wrong side of value1, the same antisymmetry bug
      // with LONG as type1 instead (#5900 review follow-up).
      return compareWideningLong((Number) value1, type2, value2);

    case BinaryTypes.TYPE_STRING: {
      if (value1 instanceof byte[] bytes1) {
        if (value2 instanceof byte[] bytes)
          return UnsignedBytesComparator.BEST_COMPARATOR.compare(bytes1, bytes);
        else
          return UnsignedBytesComparator.BEST_COMPARATOR.compare(bytes1,
              ((String) value2).getBytes(DatabaseFactory.getDefaultCharset()));
      }

      switch (type2) {
      case BinaryTypes.TYPE_INT:
      case BinaryTypes.TYPE_SHORT:
      case BinaryTypes.TYPE_BYTE:
      case BinaryTypes.TYPE_LONG:
      case BinaryTypes.TYPE_FLOAT:
      case BinaryTypes.TYPE_DOUBLE:
      case BinaryTypes.TYPE_DECIMAL:
      case BinaryTypes.TYPE_BOOLEAN:
      case BinaryTypes.TYPE_DATE:
      case BinaryTypes.TYPE_DATETIME:
      case BinaryTypes.TYPE_DATETIME_SECOND:
      case BinaryTypes.TYPE_DATETIME_MICROS:
      case BinaryTypes.TYPE_DATETIME_NANOS:
        // A String value1 against a numeric/boolean/date value2 must agree with the reverse call - delegate to
        // the other side's own comparator and negate, rather than falling through to a lexicographic compareTo()
        // that silently ignores type2 and breaks antisymmetry the same way the narrowing branches did before this
        // fix (e.g. compare("2", STRING, 10, INT) and its reverse both answered "greater"). The DATE/DATETIME
        // branch below already parses a String operand via DateUtils.dateTimeToTimestampInferringStringPrecision(),
        // so this reuses that parsing rather than duplicating it (issue #5947).
        return -compare(value2, type2, value1, type1);

      default:
        // TWO STRINGS ARE ORDERED THE WAY THE PAGES ORDER THEM - BY UNSIGNED UTF-8 BYTES, NOT BY UTF-16 CODE UNITS.
        // String.compareTo() disagrees with the page order for any non-BMP character (a surrogate pair, 0xD800-0xDBFF
        // lead unit, but a 0xF0-0xF4 lead byte) against a BMP character above U+E000, so the range cursor's stop
        // condition, which compares the un-encoded bounds through here, ended a scan before emitting anything
        // (issue #6997)
        return compareStrings((String) value1, value2.toString());
      }
    }

    case BinaryTypes.TYPE_DOUBLE:
    case BinaryTypes.TYPE_FLOAT: {
      // FLOAT always widens losslessly into double (the reverse direction is what loses precision), so both
      // share this branch instead of FLOAT narrowing the other operand down to float's 24-bit mantissa - the
      // same narrow-instead-of-widen bug as INT/SHORT/BYTE/LONG, just for the floating types (#5900 review
      // follow-up).
      final double v1 = ((Number) value1).doubleValue();
      final double v2;

      switch (type2) {
      case BinaryTypes.TYPE_INT:
      case BinaryTypes.TYPE_SHORT:
      case BinaryTypes.TYPE_LONG:
      case BinaryTypes.TYPE_DATETIME:
      case BinaryTypes.TYPE_DATE:
      case BinaryTypes.TYPE_BYTE:
      case BinaryTypes.TYPE_DECIMAL:
      case BinaryTypes.TYPE_FLOAT:
      case BinaryTypes.TYPE_DOUBLE:
        v2 = ((Number) value2).doubleValue();
        break;

      case BinaryTypes.TYPE_BOOLEAN:
        v2 = (Boolean) value2 ? 1 : 0;
        break;

      case BinaryTypes.TYPE_STRING:
        v2 = Double.parseDouble((String) value2);
        break;

      default:
        return -1;
      }

      return Double.compare(v1, v2);
    }

    case BinaryTypes.TYPE_BOOLEAN: {
      final int v1 = (Boolean) value1 ? 1 : 0;

      switch (type2) {
      case BinaryTypes.TYPE_INT:
      case BinaryTypes.TYPE_SHORT:
      case BinaryTypes.TYPE_BYTE:
      case BinaryTypes.TYPE_LONG:
      case BinaryTypes.TYPE_DATETIME:
      case BinaryTypes.TYPE_DATE:
      case BinaryTypes.TYPE_DECIMAL:
      case BinaryTypes.TYPE_FLOAT:
      case BinaryTypes.TYPE_DOUBLE:
        // Reuse the same widening comparator INT/SHORT/BYTE use as type1: narrowing a wide/floating operand to a
        // `byte` here would be the identical truncation bug this class just eliminated for those three (#5900).
        return compareNarrowIntegral(v1, type2, value2);

      case BinaryTypes.TYPE_BOOLEAN:
        return Integer.compare(v1, (Boolean) value2 ? 1 : 0);

      case BinaryTypes.TYPE_STRING:
        return Integer.compare(v1, Boolean.parseBoolean((String) value2) ? 1 : 0);

      default:
        return -1;
      }
    }
    case BinaryTypes.TYPE_DATE:
    case BinaryTypes.TYPE_DATETIME:
    case BinaryTypes.TYPE_DATETIME_SECOND:
    case BinaryTypes.TYPE_DATETIME_MICROS:
    case BinaryTypes.TYPE_DATETIME_NANOS: {
      final ChronoUnit higherPrecision = DateUtils.getHigherPrecision(value1, value2);
      final long v1 = DateUtils.dateTimeToTimestampInferringStringPrecision(value1, higherPrecision);
      final long v2 = DateUtils.dateTimeToTimestampInferringStringPrecision(value2, higherPrecision);
      return Long.compare(v1, v2);
    }

    case BinaryTypes.TYPE_BINARY: {
      switch (type2) {
      case BinaryTypes.TYPE_BINARY: {
        // Handle both byte[] and Binary objects
        if (value1 instanceof byte[] bytes1) {
          if (value2 instanceof byte[] bytes2) {
            return UnsignedBytesComparator.BEST_COMPARATOR.compare(bytes1, bytes2);
          } else if (value2 instanceof Binary binary2) {
            return -compareBytes(binary2.getContent(), bytes1);
          }
        } else if (value1 instanceof Binary binary1) {
          if (value2 instanceof byte[] bytes2) {
            return compareBytes(binary1.getContent(), bytes2);
          } else if (value2 instanceof Binary binary2) {
            return binary1.compareTo(binary2);
          }
        }
        throw new IllegalArgumentException(
            "Invalid binary type for comparison: " + value1.getClass() + " and " + value2.getClass());
      }
      }
      throw new UnsupportedOperationException("Comparing binary types");
    }

    case BinaryTypes.TYPE_DECIMAL: {
      switch (type2) {
      case BinaryTypes.TYPE_INT:
        return ((BigDecimal) value1).compareTo(new BigDecimal((Integer) value2));
      case BinaryTypes.TYPE_SHORT:
        return ((BigDecimal) value1).compareTo(new BigDecimal((Short) value2));
      case BinaryTypes.TYPE_LONG:
      case BinaryTypes.TYPE_DATETIME:
      case BinaryTypes.TYPE_DATE:
        return ((BigDecimal) value1).compareTo(new BigDecimal((Long) value2));
      case BinaryTypes.TYPE_BYTE:
        return ((BigDecimal) value1).compareTo(new BigDecimal((Byte) value2));
      case BinaryTypes.TYPE_DECIMAL:
        return ((BigDecimal) value1).compareTo((BigDecimal) value2);
      case BinaryTypes.TYPE_FLOAT:
        return ((BigDecimal) value1).compareTo(BigDecimal.valueOf((Float) value2));
      case BinaryTypes.TYPE_DOUBLE:
        return ((BigDecimal) value1).compareTo(BigDecimal.valueOf((Double) value2));
      case BinaryTypes.TYPE_STRING:
        return ((BigDecimal) value1).compareTo(new BigDecimal((String) value2));
      }
      break;
    }

    case BinaryTypes.TYPE_COMPRESSED_RID:
    case BinaryTypes.TYPE_RID: {
      switch (type2) {
      case BinaryTypes.TYPE_COMPRESSED_RID:
      case BinaryTypes.TYPE_RID:
        return ((Identifiable) value1).getIdentity().compareTo(value2);
      }
    }

    case BinaryTypes.TYPE_LIST: {
      switch (type2) {
      case BinaryTypes.TYPE_LIST:
        final List v1 = value1.getClass().isArray() ? arrayToList(value1) : (List) value1;
        final List v2 = value2.getClass().isArray() ? arrayToList(value2) : (List) value2;

        return CollectionUtils.compare(v1, v2);
      }
      break;
    }

    case BinaryTypes.TYPE_MAP: {
      switch (type2) {
      case BinaryTypes.TYPE_MAP:
        return CollectionUtils.compare((Map) value1, (Map) value2);
      }
      break;
    }

    }

    throw new IllegalArgumentException("Comparison between type " + type1 + " and " + type2 + " not supported");
  }

@Override
  public MatchFilterItem visitMatchFilterItem(final SQLParser.MatchFilterItemContext ctx) {
    final MatchFilterItem item = new MatchFilterItem();

    // Handle special case for BUCKET_IDENTIFIER (bucket:name) and BUCKET_NUMBER_IDENTIFIER (bucket:123)
    if (ctx.BUCKET_IDENTIFIER() != null) {
      // Extract the bucket name from the token (after the colon)
      final String tokenText = ctx.BUCKET_IDENTIFIER().getText();
      final String bucketName = tokenText.substring(7); // Remove "bucket:" prefix
      item.bucketName = new Identifier(bucketName);

      // Expression is optional for these special tokens
      if (ctx.expression() != null) {
        // This shouldn't normally happen for bucket identifier, but handle it
      }
      return item;
    }

    if (ctx.BUCKET_NUMBER_IDENTIFIER() != null) {
      // Extract the bucket number from the token (after the colon)
      final String tokenText = ctx.BUCKET_NUMBER_IDENTIFIER().getText();
      final String bucketNumStr = tokenText.substring(7); // Remove "bucket:" prefix
      item.bucketId = new PInteger().setValue(Integer.parseInt(bucketNumStr));
      return item;
    }

    // Get the key (could be identifier or keyword token)
    final Identifier key;
    final Object keyObj = visit(ctx.matchFilterItemKey());
    if (keyObj instanceof Identifier) {
      key = (Identifier) keyObj;
    } else {
      // Shouldn't happen with current grammar, but handle gracefully
      throw new IllegalStateException("Unexpected matchFilterItemKey type: " +
          (keyObj != null ? keyObj.getClass().getName() : "null"));
    }

    final Object valueObj = visit(ctx.expression());

    final String keyName = key.getStringValue().toLowerCase();

    // Map the key to the appropriate field
    switch (keyName) {
    case "type":
      item.typeName = (Expression) valueObj;
      break;
    case "types":
      item.typeNames = (Expression) valueObj;
      break;
    case "bucket":
      // Could be bucket name (identifier) or bucket id (integer)
      if (valueObj instanceof PInteger) {
        item.bucketId = (PInteger) valueObj;
      } else if (valueObj instanceof final Expression expr) {
        if (expr.mathExpression instanceof final BaseExpression baseExpr) {
          if (baseExpr.number instanceof PInteger) {
            item.bucketId = (PInteger) baseExpr.number;
          } else if (baseExpr.identifier != null) {
            // Extract the Identifier directly to avoid backtick escaping via toString()
            final Object suffix = baseExpr.identifier.suffix;
            if (suffix instanceof final SuffixIdentifier si && si.identifier != null) {
              item.bucketName = si.identifier;
            }
          }
        }
      }
      if (item.bucketId == null && item.bucketName == null) {
        throw new CommandSQLParsingException("MATCH bucket filter must be an integer ID or an identifier, got: " + valueObj);
      }
      break;
    case "rid":
      if (valueObj instanceof Rid) {
        item.rid = (Rid) valueObj;
      } else if (valueObj instanceof final Expression expr) {
        if (expr.rid != null) {
          // Literal RID such as #13:32960 - visitRidLiteral wraps the Rid in an Expression
          item.rid = expr.rid;
        } else {
          // Parameterized or computed RID such as :rid - keep the expression and resolve it against
          // the command context at plan time (Rid.toRecordId)
          final Rid computed = new Rid();
          computed.expression = expr;
          item.rid = computed;
        }
      } else {
        throw new CommandSQLParsingException(
            "MATCH rid filter must be a RID or an expression evaluating to a RID, got: " + valueObj);
      }
      break;
    case "as":
      // Extract identifier name from the expression
      if (valueObj instanceof BaseIdentifier) {
        // Create Identifier from the string representation
        final StringBuilder sb = new StringBuilder();
        ((BaseIdentifier) valueObj).toString(Collections.emptyMap(), sb);
        item.alias = new Identifier(sb.toString());
      } else if (valueObj instanceof final BaseExpression baseExpr) {
        if (baseExpr.identifier != null) {
          final StringBuilder sb = new StringBuilder();
          baseExpr.identifier.toString(Collections.emptyMap(), sb);
          item.alias = new Identifier(sb.toString());
        } else {
          item.alias = new Identifier(valueObj.toString().replace("'", ""));
        }
      } else {
        // If value is a string literal, extract the alias name
        item.alias = new Identifier(valueObj.toString().replace("'", ""));
      }
      break;
    case "where":
      if (valueObj instanceof WhereClause) {
        item.filter = (WhereClause) valueObj;
      } else if (valueObj instanceof BooleanExpression) {
        final WhereClause whereClause = new WhereClause();
        whereClause.baseExpression = (BooleanExpression) valueObj;
        item.filter = whereClause;
      } else if (valueObj instanceof final Expression expr) {
        // Expression containing the WHERE condition: where:(name = 'n1')
        // Check if it's a BaseExpression containing a boolean value like (true) or (false)
        if (expr.mathExpression instanceof final BaseExpression baseExpr) {
          if (baseExpr.expression != null && baseExpr.expression.booleanValue != null) {
            // Handle boolean literals wrapped in BaseExpression: where: (true)
            final WhereClause whereClause = new WhereClause();
            final BooleanExpression boolExpr = createBooleanLiteral(baseExpr.expression.booleanValue);
            whereClause.baseExpression = boolExpr;
            item.filter = whereClause;
          }
        }
        // For parenthesized conditions like (name = 'n1'), mathExpression is a ParenthesisExpression
        else if (expr.mathExpression instanceof final ParenthesisExpression parenExpr) {
          // Extract the inner expression's whereCondition from the parentheses
          if (parenExpr.expression != null && parenExpr.expression.whereCondition != null) {
            item.filter = parenExpr.expression.whereCondition;
          } else if (parenExpr.expression != null && parenExpr.expression.booleanValue != null) {
            // Handle boolean literals like (true) or (false)
            final WhereClause whereClause = new WhereClause();
            final BooleanExpression boolExpr = createBooleanLiteral(parenExpr.expression.booleanValue);
            whereClause.baseExpression = boolExpr;
            item.filter = whereClause;
          }
        } else if (expr.whereCondition != null) {
          // Direct WHERE clause
          item.filter = expr.whereCondition;
        } else if (expr.booleanValue != null) {
          // Direct boolean literal
          final WhereClause whereClause = new WhereClause();
          final BooleanExpression boolExpr = createBooleanLiteral(expr.booleanValue);
          whereClause.baseExpression = boolExpr;
          item.filter = whereClause;
        }
      }
      break;
    case "while":
      if (valueObj instanceof WhereClause) {
        item.whileCondition = (WhereClause) valueObj;
      } else if (valueObj instanceof BooleanExpression) {
        final WhereClause whereClause = new WhereClause();
        whereClause.baseExpression = (BooleanExpression) valueObj;
        item.whileCondition = whereClause;
      } else if (valueObj instanceof final Expression expr) {
        // Expression containing the WHILE condition
        // Check if it's a BaseExpression containing a boolean value like (true) or (false)
        if (expr.mathExpression instanceof final BaseExpression baseExpr) {
          if (baseExpr.expression != null && baseExpr.expression.booleanValue != null) {
            // Handle boolean literals wrapped in BaseExpression: while: (true)
            final WhereClause whereClause = new WhereClause();
            final BooleanExpression boolExpr = createBooleanLiteral(baseExpr.expression.booleanValue);
            whereClause.baseExpression = boolExpr;
            item.whileCondition = whereClause;
          }
        }
        // For parenthesized conditions, mathExpression is a ParenthesisExpression
        else if (expr.mathExpression instanceof final ParenthesisExpression parenExpr) {
          // Extract the inner expression's whereCondition from the parentheses
          if (parenExpr.expression != null && parenExpr.expression.whereCondition != null) {
            item.whileCondition = parenExpr.expression.whereCondition;
          } else if (parenExpr.expression != null && parenExpr.expression.booleanValue != null) {
            // Handle boolean literals like (true) or (false)
            final WhereClause whereClause = new WhereClause();
            final BooleanExpression boolExpr = createBooleanLiteral(parenExpr.expression.booleanValue);
            whereClause.baseExpression = boolExpr;
            item.whileCondition = whereClause;
          }
        } else if (expr.whereCondition != null) {
          // Direct WHERE clause (used for WHILE)
          item.whileCondition = expr.whereCondition;
        } else if (expr.booleanValue != null) {
          // Direct boolean literal
          final WhereClause whereClause = new WhereClause();
          final BooleanExpression boolExpr = createBooleanLiteral(expr.booleanValue);
          whereClause.baseExpression = boolExpr;
          item.whileCondition = whereClause;
        }
      }
      break;
    case "maxdepth":
      if (valueObj instanceof PInteger) {
        item.maxDepth = (PInteger) valueObj;
      } else if (valueObj instanceof final BaseExpression baseExpr) {
        if (baseExpr.number instanceof PInteger) {
          item.maxDepth = (PInteger) baseExpr.number;
        }
      } else if (valueObj instanceof final Expression expr) {
        if (expr.mathExpression instanceof final BaseExpression baseExpr) {
          if (baseExpr.number instanceof PInteger) {
            item.maxDepth = (PInteger) baseExpr.number;
          }
        }
      }
      break;
    case "depth":
      // depth can be an ArrayRangeSelector like depth: [0..3]
      if (valueObj instanceof ArrayRangeSelector) {
        item.depth = (ArrayRangeSelector) valueObj;
      } else if (valueObj instanceof BaseExpression) {
        // Try to extract range from expression
        // For now, just skip if it's not already an ArrayRangeSelector
      }
      break;
    case "optional":
      item.optional = true;
      break;
    case "depthalias":
      // Extract identifier name from the expression
      if (valueObj instanceof BaseIdentifier) {
        final StringBuilder sb = new StringBuilder();
        ((BaseIdentifier) valueObj).toString(Collections.emptyMap(), sb);
        item.depthAlias = new Identifier(sb.toString());
      } else if (valueObj instanceof final BaseExpression baseExpr) {
        if (baseExpr.identifier != null) {
          final StringBuilder sb = new StringBuilder();
          baseExpr.identifier.toString(Collections.emptyMap(), sb);
          item.depthAlias = new Identifier(sb.toString());
        }
      } else if (valueObj instanceof final Expression expr) {
        if (expr.mathExpression instanceof final BaseExpression baseExpr) {
          if (baseExpr.identifier != null) {
            final StringBuilder sb = new StringBuilder();
            baseExpr.identifier.toString(Collections.emptyMap(), sb);
            item.depthAlias = new Identifier(sb.toString());
          }
        }
      }
      break;
    case "pathalias":
      // Extract identifier name from the expression
      if (valueObj instanceof BaseIdentifier) {
        final StringBuilder sb = new StringBuilder();
        ((BaseIdentifier) valueObj).toString(Collections.emptyMap(), sb);
        item.pathAlias = new Identifier(sb.toString());
      } else if (valueObj instanceof final BaseExpression baseExpr) {
        if (baseExpr.identifier != null) {
          final StringBuilder sb = new StringBuilder();
          baseExpr.identifier.toString(Collections.emptyMap(), sb);
          item.pathAlias = new Identifier(sb.toString());
        }
      } else if (valueObj instanceof final Expression expr) {
        if (expr.mathExpression instanceof final BaseExpression baseExpr) {
          if (baseExpr.identifier != null) {
            final StringBuilder sb = new StringBuilder();
            baseExpr.identifier.toString(Collections.emptyMap(), sb);
            item.pathAlias = new Identifier(sb.toString());
          }
        }
      }
      break;
    default:
      // Unknown key - ignore or log warning
      break;
    }

    return item;
  }

public void serializeValue(final Database database, final Binary serialized, final byte type, Object value,
      final boolean applyEncryption) {
    if (value == null)
      return;
    final boolean encrypt = applyEncryption && dataEncryption != null;
    Binary content = encrypt ? new Binary() : serialized;

    switch (type) {
    case BinaryTypes.TYPE_NULL:
      break;
    case BinaryTypes.TYPE_COMPRESSED_STRING:
      content.putUnsignedNumber((Integer) value);
      break;
    case BinaryTypes.TYPE_BINARY:
      if (value instanceof byte[] bytes)
        content.putBytes(bytes);
      else if (value instanceof Binary binary)
        content.putBytes(binary.getContent());
      break;
    case BinaryTypes.TYPE_COMPRESSED_GEOMETRY:
      serializeGeometryBinary(content, (Shape) value);
      break;
    case BinaryTypes.TYPE_STRING:
      if (value instanceof byte[] bytes)
        content.putBytes(bytes);
      else if (BinaryTypes.isGeoSpatialShape(value))
        content.putString(convertShapeToWKT(value));
      else
        content.putString(value.toString());
      break;
    case BinaryTypes.TYPE_BYTE:
      content.putByte((Byte) value);
      break;
    case BinaryTypes.TYPE_BOOLEAN:
      content.putByte((byte) ((Boolean) value ? 1 : 0));
      break;
    case BinaryTypes.TYPE_SHORT:
      content.putNumber(((Number) value).shortValue());
      break;
    case BinaryTypes.TYPE_INT:
      content.putNumber(((Number) value).intValue());
      break;
    case BinaryTypes.TYPE_LONG:
      content.putNumber(((Number) value).longValue());
      break;
    case BinaryTypes.TYPE_FLOAT:
      content.putNumber(Float.floatToIntBits(((Number) value).floatValue()));
      break;
    case BinaryTypes.TYPE_DOUBLE:
      content.putNumber(Double.doubleToLongBits(((Number) value).doubleValue()));
      break;
    case BinaryTypes.TYPE_DATE:
      if (value instanceof Date date)
        content.putUnsignedNumber(date.getTime() / DateUtils.MS_IN_A_DAY);
      else if (value instanceof LocalDate date)
        content.putUnsignedNumber(date.toEpochDay());
      else
        throw new IllegalArgumentException(
            "Cannot serialize " + value.getClass() + " as DATE; expected java.util.Date or java.time.LocalDate");
      break;
    case BinaryTypes.TYPE_DATETIME_SECOND:
    case BinaryTypes.TYPE_DATETIME:
    case BinaryTypes.TYPE_DATETIME_MICROS:
    case BinaryTypes.TYPE_DATETIME_NANOS:
      serializeDateTime(database, content, value, type);
      break;
    case BinaryTypes.TYPE_DECIMAL:
      content.putNumber(((BigDecimal) value).scale());
      content.putBytes(((BigDecimal) value).unscaledValue().toByteArray());
      break;
    case BinaryTypes.TYPE_COMPRESSED_RID: {
      final RID rid = ((Identifiable) value).getIdentity();
      serialized.putNumber(rid.getBucketId());
      serialized.putNumber(rid.getPosition());
      break;
    }
    case BinaryTypes.TYPE_RID: {
      if (value instanceof Result result)
        // COMING FROM A QUERY
        value = result.getElement().get();

      final RID rid = ((Identifiable) value).getIdentity();
      serialized.putInt(rid.getBucketId());
      serialized.putLong(rid.getPosition());
      break;
    }
    case BinaryTypes.TYPE_UUID: {
      final UUID uuid = (UUID) value;
      content.putNumber(uuid.getMostSignificantBits());
      content.putNumber(uuid.getLeastSignificantBits());
      break;
    }
    case BinaryTypes.TYPE_LIST: {
      switch (value) {
      case Collection<?> list -> serializeListEntries(database, content, list, list.size(), "list", applyEncryption);
      case Object[] array -> serializeListEntries(database, content, Arrays.asList(array), array.length, "array", applyEncryption);
      case Iterable<?> iter -> {
        final List<Object> list = new ArrayList<>();
        for (Object o : iter)
          list.add(o);
        serializeListEntries(database, content, list, list.size(), "iterable", applyEncryption);
      }
      default -> {
        // PRIMITIVE ARRAY (component type not matched by the cases above)
        final int length = Array.getLength(value);
        content.putUnsignedNumber(length);
        for (int i = 0; i < length; ++i) {
          final Object entryValue = Array.get(value, i);
          try {
            byte entryType = BinaryTypes.getTypeFromValue(entryValue, null);
            Object valueToWrite = entryValue;
            if (entryType == -1) {
              LogManager.instance()
                  .log(BinaryTypes.class, Level.WARNING,
                      "Cannot serialize entry in array of type %s, value %s. Stored as null",
                      entryValue.getClass(), entryValue);
              entryType = BinaryTypes.TYPE_NULL;
              valueToWrite = null;
            }
            content.putByte(entryType);
            serializeValue(database, content, entryType, valueToWrite, applyEncryption);
          } catch (Exception e) {
            // The element's own toString() is not a substitute for knowing which nested serializeValue() threw and
            // why, so the cause travels on both paths - the log and the exception (issue #7247).
            LogManager.instance().log(this, Level.SEVERE, "Error on serializing array value for element %d = '%s'", e,
                i, entryValue);
            throw new SerializationException(
                "Error on serializing array value for element " + i + " = '" + entryValue + "'", e);
          }
        }
      }
      }
      break;
    }
    case BinaryTypes.TYPE_MAP: {
      final Dictionary dictionary = database.getSchema().getDictionary();

      if (value instanceof JSONObject object)
        value = object.toMap();

      final Map<Object, Object> map = (Map<Object, Object>) value;
      final int mapSize = map.size();
      // Pre-resolve types so the count matches what is written. A partially-written entry
      // (key without value) desyncs the reader and corrupts the record.
      // An invalid key drops the entry; an invalid value preserves the key and stores null.
      final Object[] keys = new Object[mapSize];
      final Object[] values = new Object[mapSize];
      final byte[] keyTypes = new byte[mapSize];
      final byte[] valueTypes = new byte[mapSize];
      int validCount = 0;
      for (final Map.Entry<Object, Object> entry : map.entrySet()) {
        try {
          Object entryKey = entry.getKey();
          byte entryKeyType = BinaryTypes.getTypeFromValue(entryKey, null);
          if (entryKeyType == -1) {
            LogManager.instance()
                .log(BinaryTypes.class, Level.WARNING,
                    "Cannot serialize entry key in map of type %s, value %s. The entry will be ignored",
                    entryKey.getClass(), entryKey);
            continue;
          }

          Object entryValue = entry.getValue();
          byte entryValueType = BinaryTypes.getTypeFromValue(entryValue, null);
          if (entryValueType == -1) {
            LogManager.instance()
                .log(BinaryTypes.class, Level.WARNING,
                    "Cannot serialize entry value in map of type %s, value %s. Stored as null",
                    entryValue.getClass(), entryValue);
            entryValueType = BinaryTypes.TYPE_NULL;
            entryValue = null;
          }

          if (entryKey != null && entryKeyType == BinaryTypes.TYPE_STRING) {
            final int id = dictionary.getIdByName((String) entryKey, false);
            if (id > -1) {
              // COMPRESSED STRING AS MAP KEY
              entryKeyType = BinaryTypes.TYPE_COMPRESSED_STRING;
              entryKey = id;
            }
          }

          keys[validCount] = entryKey;
          values[validCount] = entryValue;
          keyTypes[validCount] = entryKeyType;
          valueTypes[validCount] = entryValueType;
          ++validCount;
        } catch (Exception e) {
          LogManager.instance().log(this, Level.SEVERE, "Error on serializing map value for key '%s' = '%s'",
              entry.getKey(), entry.getValue());
          throw new SerializationException(
              "Error on serializing map value for key '" + entry.getKey() + "' = '" + entry.getValue() + "'", e);
        }
      }
      content.putUnsignedNumber(validCount);
      for (int i = 0; i < validCount; ++i) {
        content.putByte(keyTypes[i]);
        serializeValue(database, content, keyTypes[i], keys[i], applyEncryption);
        content.putByte(valueTypes[i]);
        serializeValue(database, content, valueTypes[i], values[i], applyEncryption);
      }
      break;
    }
    case BinaryTypes.TYPE_EMBEDDED: {
      final Document document = (Document) value;
      final long schemaId = database.getSchema().getDictionary().getIdByName(document.getTypeName(), false);
      if (schemaId == -1)
        throw new IllegalArgumentException("Cannot find type '" + document.getTypeName() + "' declared in embedded document");
      content.putUnsignedNumber(schemaId);

      final Binary header = new Binary(8192);
      header.setAllocationChunkSize(2048);
      final Binary body = new Binary(8192);
      body.setAllocationChunkSize(2048);

      header.putByte(EmbeddedDocument.RECORD_TYPE);
      serializeProperties(database, document, header, body);

      content.putUnsignedNumber(header.size());
      content.append(header);
      break;
    }
    case BinaryTypes.TYPE_ARRAY_OF_SHORTS: {
      // `Array.getShort()` is the fast primitive-array path: java.lang.reflect.Array's typed getters reject a boxed
      // Short[] with IllegalArgumentException ("not an array of primitive type"), so a wrapper array - now also
      // classified TYPE_ARRAY_OF_SHORTS, issue #6464 - is unboxed explicitly instead.
      if (value instanceof short[] shorts) {
        content.putUnsignedNumber(shorts.length);
        for (final short v : shorts)
          content.putNumber(v);
      } else {
        final Short[] shorts = (Short[]) value;
        content.putUnsignedNumber(shorts.length);
        for (final Short v : shorts)
          content.putNumber(v);
      }
      break;
    }
    case BinaryTypes.TYPE_ARRAY_OF_INTEGERS: {
      if (value instanceof int[] ints) {
        content.putUnsignedNumber(ints.length);
        for (final int v : ints)
          content.putNumber(v);
      } else {
        final Integer[] ints = (Integer[]) value;
        content.putUnsignedNumber(ints.length);
        for (final Integer v : ints)
          content.putNumber(v);
      }
      break;
    }
    case BinaryTypes.TYPE_ARRAY_OF_LONGS: {
      if (value instanceof long[] longs) {
        content.putUnsignedNumber(longs.length);
        for (final long v : longs)
          content.putNumber(v);
      } else {
        final Long[] longs = (Long[]) value;
        content.putUnsignedNumber(longs.length);
        for (final Long v : longs)
          content.putNumber(v);
      }
      break;
    }
    case BinaryTypes.TYPE_ARRAY_OF_FLOATS: {
      if (value instanceof float[] floats) {
        content.putUnsignedNumber(floats.length);
        for (final float v : floats)
          content.putNumber(Float.floatToIntBits(v));
      } else {
        final Float[] floats = (Float[]) value;
        content.putUnsignedNumber(floats.length);
        for (final Float v : floats)
          content.putNumber(Float.floatToIntBits(v));
      }
      break;
    }
    case BinaryTypes.TYPE_ARRAY_OF_DOUBLES: {
      if (value instanceof double[] doubles) {
        content.putUnsignedNumber(doubles.length);
        for (final double v : doubles)
          content.putNumber(Double.doubleToLongBits(v));
      } else {
        final Double[] doubles = (Double[]) value;
        content.putUnsignedNumber(doubles.length);
        for (final Double v : doubles)
          content.putNumber(Double.doubleToLongBits(v));
      }
      break;
    }
    default:
      LogManager.instance().log(this, Level.INFO, "Error on serializing value '%s', type not supported", value);
    }

    if (encrypt) {
      switch (type) {
      case BinaryTypes.TYPE_NULL:
      case BinaryTypes.TYPE_COMPRESSED_RID:
      case BinaryTypes.TYPE_RID:
        break;
      default:
        serialized.putBytes(dataEncryption.encrypt(content.toByteArray()));
      }
    }
  }

Expression parseExpressionFromText(final ParseTree node) {
    // All recursive searches below use a length guard: only match when the found
    // context covers (almost) the full node text, preventing mis-parsing of
    // func(CASE ...) as just the inner CASE.  The - 2 allows for whitespace.
    final String nodeText = node.getText();

    final Cypher25Parser.CaseExpressionContext caseCtx = findCaseExpressionRecursive(node);
    if (caseCtx != null && caseCtx.getText().length() >= nodeText.length() - 2)
      return parseCaseExpression(caseCtx);

    final Cypher25Parser.ExtendedCaseExpressionContext extCaseCtx = findExtendedCaseExpressionRecursive(node);
    if (extCaseCtx != null && extCaseCtx.getText().length() >= nodeText.length() - 2)
      return parseExtendedCaseExpression(extCaseCtx);

    // Check for EXISTS expressions
    final Cypher25Parser.ExistsExpressionContext existsCtx = findExistsExpressionRecursive(node);
    if (existsCtx != null && existsCtx.getText().length() >= nodeText.length() - 2)
      return parseExistsExpression(existsCtx);

    // Check for COLLECT { ... } subqueries
    final Cypher25Parser.CollectExpressionContext collectCtx = findCollectExpressionRecursive(node);
    if (collectCtx != null && collectCtx.getText().length() >= nodeText.length() - 2)
      return parseCollectExpression(collectCtx);

    // Check for COUNT { ... } subqueries
    final Cypher25Parser.CountExpressionContext countCtx = findCountExpressionRecursive(node);
    if (countCtx != null && countCtx.getText().length() >= nodeText.length() - 2)
      return parseCountExpression(countCtx);

    // Check for logical expressions (AND, OR, XOR, NOT) in the parse tree
    // This handles cases like (a AND b) appearing as children of comparisons
    if (node instanceof Cypher25Parser.ExpressionContext)
      return parseExpression((Cypher25Parser.ExpressionContext) node);

    if (node instanceof Cypher25Parser.Expression11Context) {
      final Expression logicalExpr = tryParseLogicalExpression((Cypher25Parser.Expression11Context) node);
      if (logicalExpr != null)
        return logicalExpr;
    }

    if (node instanceof Cypher25Parser.Expression10Context) {
      final Cypher25Parser.Expression10Context e10 = (Cypher25Parser.Expression10Context) node;
      if (e10.expression9().size() > 1) {
        Expression result = parseExpressionFromExpression9(e10.expression9().get(0));
        for (int i = 1; i < e10.expression9().size(); i++) {
          final Expression right = parseExpressionFromExpression9(e10.expression9().get(i));
          result = new TernaryLogicalExpression(TernaryLogicalExpression.Operator.AND, result, right);
        }
        return result;
      }
      if (e10.expression9().size() == 1)
        return parseExpressionFromExpression9(e10.expression9().get(0));
    }

    if (node instanceof Cypher25Parser.Expression9Context)
      return parseExpressionFromExpression9((Cypher25Parser.Expression9Context) node);

    // Handle Expression2 with postfix operations (property access, indexing, slicing)
    // Must be checked early to avoid inner list/map literals being matched first
    if (node instanceof Cypher25Parser.Expression2Context) {
      final Cypher25Parser.Expression2Context e2 = (Cypher25Parser.Expression2Context) node;
      if (!e2.postFix().isEmpty())
        return parseExpression2WithPostfix(e2);
      // No postfix — delegate to expression1
      return parseExpressionFromText(e2.expression1());
    }

    // Handle Expression8 (comparison operators: =, <>, <, >, <=, >=)
    if (node instanceof Cypher25Parser.Expression8Context) {
      final Cypher25Parser.Expression8Context expr8 = (Cypher25Parser.Expression8Context) node;
      if (expr8.expression7().size() > 1)
        return parseComparisonFromExpression8(expr8);
      // Single Expression7 child, delegate to it
      if (!expr8.expression7().isEmpty())
        return parseExpressionFromText(expr8.expression7().get(0));
    }

    // Handle Expression7 (IS NULL, STARTS WITH, ENDS WITH, CONTAINS, IN, label check, IS TYPED)
    if (node instanceof Cypher25Parser.Expression7Context) {
      final Cypher25Parser.Expression7Context expr7 = (Cypher25Parser.Expression7Context) node;
      final Cypher25Parser.ComparisonExpression6Context comp = expr7.comparisonExpression6();
      if (comp instanceof Cypher25Parser.NullComparisonContext)
        return parseIsNullExpression((Cypher25Parser.NullComparisonContext) comp);
      if (comp instanceof Cypher25Parser.StringAndListComparisonContext)
        return parseStringComparisonExpression(expr7);
      if (comp instanceof Cypher25Parser.LabelComparisonContext)
        return parseLabelComparisonExpression(expr7);
      if (comp instanceof Cypher25Parser.TypeComparisonContext)
        return parseIsTypedExpression((Cypher25Parser.TypeComparisonContext) comp);
      // No comparison, delegate to expression6
      return parseExpressionFromText(expr7.expression6());
    }

    // Handle intermediate expression contexts by walking down the grammar hierarchy.
    // This prevents recursive searches from crossing parenthesized boundaries.
    if (node instanceof Cypher25Parser.Expression6Context) {
      final Cypher25Parser.Expression6Context e6 = (Cypher25Parser.Expression6Context) node;
      if (e6.expression5().size() > 1)
        return parseArithmeticExpression6(e6);
      return parseExpressionFromText(e6.expression5().get(0));
    }

    if (node instanceof Cypher25Parser.Expression5Context) {
      final Cypher25Parser.Expression5Context e5 = (Cypher25Parser.Expression5Context) node;
      if (e5.expression4().size() > 1)
        return parseArithmeticExpression5(e5);
      return parseExpressionFromText(e5.expression4().get(0));
    }

    if (node instanceof Cypher25Parser.Expression4Context) {
      final Cypher25Parser.Expression4Context e4 = (Cypher25Parser.Expression4Context) node;
      if (e4.expression3().size() > 1)
        return parseArithmeticExpression4(e4);
      return parseExpressionFromText(e4.expression3().get(0));
    }

    if (node instanceof Cypher25Parser.Expression3Context) {
      return parseArithmeticExpression3((Cypher25Parser.Expression3Context) node);
    }

    // Handle Expression1 (atom level: literals, variables, function calls, list predicates, etc.)
    if (node instanceof Cypher25Parser.Expression1Context) {
      final Cypher25Parser.Expression1Context e1 = (Cypher25Parser.Expression1Context) node;
      if (e1.listItemsPredicate() != null)
        return parseListItemsPredicate(e1.listItemsPredicate());
      if (e1.functionInvocation() != null)
        return parseFunctionInvocation(e1.functionInvocation());
      if (e1.caseExpression() != null)
        return parseCaseExpression(e1.caseExpression());
      if (e1.extendedCaseExpression() != null)
        return parseExtendedCaseExpression(e1.extendedCaseExpression());
      if (e1.listLiteral() != null)
        return parseListLiteral(e1.listLiteral());
      if (e1.mapProjection() != null)
        return parseMapProjection(e1.mapProjection());
      if (e1.listComprehension() != null)
        return parseListComprehension(e1.listComprehension());
      if (e1.patternComprehension() != null)
        return parsePatternComprehension(e1.patternComprehension());
      if (e1.reduceExpression() != null)
        return parseReduceExpression(e1.reduceExpression());
      if (e1.allReduceExpression() != null)
        return parseAllReduceExpression(e1.allReduceExpression());
      if (e1.existsExpression() != null)
        return parseExistsExpression(e1.existsExpression());
      if (e1.collectExpression() != null)
        return parseCollectExpression(e1.collectExpression());
      if (e1.countExpression() != null)
        return parseCountExpression(e1.countExpression());
      if (e1.countStar() != null) {
        final List<Expression> e1Args = new ArrayList<>();
        e1Args.add(new StarExpression());
        return new FunctionCallExpression("count", e1Args, false);
      }
      if (e1.parenthesizedExpression() != null)
        return parseExpression(e1.parenthesizedExpression().expression());
      if (e1.shortestPathExpression() != null)
        return parseShortestPathExpression(e1.shortestPathExpression());
      if (e1.vectorFunction() != null)
        return parseVectorFunction(e1.vectorFunction());
      if (e1.vectorNormFunction() != null)
        return parseVectorNormFunction(e1.vectorNormFunction());
      if (e1.vectorDistanceFunction() != null)
        return parseVectorDistanceFunction(e1.vectorDistanceFunction());
      if (e1.trimFunction() != null)
        return parseTrimFunction(e1.trimFunction());
      if (e1.normalizeFunction() != null)
        return parseNormalizeFunction(e1.normalizeFunction());
      // Check for map literal
      final Cypher25Parser.MapContext e1MapCtx = findMapRecursive(e1);
      if (e1MapCtx != null)
        return parseMapLiteralExpression(e1MapCtx);
      // Fallback: parse as variable or literal
      // (will be handled by the text-based parsing below)
    }

    // Check for IS NULL / IS NOT NULL expressions BEFORE parenthesized expressions
    // because (a AND b) IS NULL should be parsed as IS_NULL(a AND b), not just (a AND b)
    final Cypher25Parser.NullComparisonContext nullCtx = findNullComparisonRecursive(node);
    if (nullCtx != null)
      return parseIsNullExpression(nullCtx);

    // Check for IS [NOT] TYPED / :: type expressions before parenthesized expressions for the
    // same reason (issue #3365 section 3.3).
    final Cypher25Parser.TypeComparisonContext typeCtx = findTypeComparisonRecursive(node);
    if (typeCtx != null)
      return parseIsTypedExpression(typeCtx);

    // Check for parenthesized expressions containing logical operators
    final Cypher25Parser.ParenthesizedExpressionContext parenCtx = findParenthesizedExpressionRecursive(node);
    if (parenCtx != null)
      return parseExpression(parenCtx.expression());

    // Check for arithmetic expressions (+ - * / % ^)
    final Cypher25Parser.Expression6Context arith6Ctx = findArithmeticExpression6Recursive(node);
    if (arith6Ctx != null)
      return parseArithmeticExpression6(arith6Ctx);

    final Cypher25Parser.Expression5Context arith5Ctx = findArithmeticExpression5Recursive(node);
    if (arith5Ctx != null)
      return parseArithmeticExpression5(arith5Ctx);

    // Check for list predicates (all/any/none/single) BEFORE function invocations
    // to avoid misinterpreting them as regular function calls
    final Cypher25Parser.ListItemsPredicateContext listPredCtx = findListItemsPredicateRecursive(node);
    if (listPredCtx != null)
      return parseListItemsPredicate(listPredCtx);

    // Check for reduce expressions
    final Cypher25Parser.ReduceExpressionContext reduceCtx = findReduceExpressionRecursive(node);
    if (reduceCtx != null)
      return parseReduceExpression(reduceCtx);

    // Check for allReduce expressions
    final Cypher25Parser.AllReduceExpressionContext allReduceCtx = findAllReduceExpressionRecursive(node);
    if (allReduceCtx != null)
      return parseAllReduceExpression(allReduceCtx);

    // Check for list comprehensions [x IN list | expr]
    final Cypher25Parser.ListComprehensionContext listCompCtx = findListComprehensionRecursive(node);
    if (listCompCtx != null)
      return parseListComprehension(listCompCtx);

    // Check for function invocations
    final Cypher25Parser.FunctionInvocationContext funcCtx = findFunctionInvocationRecursive(node);
    if (funcCtx != null)
      return parseFunctionInvocation(funcCtx);

    // Check for list/map literals
    final Cypher25Parser.ListLiteralContext listLitCtx = findListLiteralRecursive(node);
    if (listLitCtx != null)
      return parseListLiteral(listLitCtx);

    final Cypher25Parser.MapContext mapCtx = findMapRecursive(node);
    if (mapCtx != null)
      return parseMapLiteralExpression(mapCtx);

    // Fallback to text parsing
    final String text = node.getText();
    return parseExpressionText(text);
  }

static List<PostgresCatalogToken> tokenize(final String query) {
    final List<PostgresCatalogToken> tokens = new ArrayList<>();
    final int length = query.length();
    int i = 0;

    while (i < length) {
      final char c = query.charAt(i);

      if (Character.isWhitespace(c)) {
        ++i;
        continue;
      }

      // -- line comment
      if (c == '-' && i + 1 < length && query.charAt(i + 1) == '-') {
        while (i < length && query.charAt(i) != '\n')
          ++i;
        continue;
      }

      // /* block comment */, which PostgreSQL allows to nest
      if (c == '/' && i + 1 < length && query.charAt(i + 1) == '*') {
        int depth = 0;
        while (i < length) {
          if (query.charAt(i) == '/' && i + 1 < length && query.charAt(i + 1) == '*') {
            ++depth;
            i += 2;
          } else if (query.charAt(i) == '*' && i + 1 < length && query.charAt(i + 1) == '/') {
            --depth;
            i += 2;
            if (depth == 0)
              break;
          } else
            ++i;
        }
        if (depth != 0)
          return null;
        continue;
      }

      // 'string literal', with '' as the embedded quote
      if (c == '\'') {
        final StringBuilder value = new StringBuilder();
        ++i;
        boolean closed = false;
        while (i < length) {
          final char ch = query.charAt(i);
          if (ch == '\'') {
            if (i + 1 < length && query.charAt(i + 1) == '\'') {
              value.append('\'');
              i += 2;
              continue;
            }
            ++i;
            closed = true;
            break;
          }
          value.append(ch);
          ++i;
        }
        if (!closed)
          return null;
        tokens.add(new PostgresCatalogToken(Type.STRING, value.toString()));
        continue;
      }

      // E'escape string', whose backslash escapes matter: pgjdbc writes E'%' and E'\\_' in LIKE patterns
      if ((c == 'E' || c == 'e') && i + 1 < length && query.charAt(i + 1) == '\'') {
        final StringBuilder value = new StringBuilder();
        i += 2;
        boolean closed = false;
        while (i < length) {
          final char ch = query.charAt(i);
          if (ch == '\\' && i + 1 < length) {
            value.append(unescape(query.charAt(i + 1)));
            i += 2;
            continue;
          }
          if (ch == '\'') {
            if (i + 1 < length && query.charAt(i + 1) == '\'') {
              value.append('\'');
              i += 2;
              continue;
            }
            ++i;
            closed = true;
            break;
          }
          value.append(ch);
          ++i;
        }
        if (!closed)
          return null;
        tokens.add(new PostgresCatalogToken(Type.STRING, value.toString()));
        continue;
      }

      // `backtick quoted identifier`. PostgreSQL does not have these, but ArcadeDB does, and the executor
      // rewrites a client's "double quoted" identifiers into them before dispatching (see
      // PostgresQuotedIdentifierRewriter), so this is the form a catalog query actually arrives in.
      if (c == '`') {
        final int end = query.indexOf('`', i + 1);
        if (end < 0)
          return null;
        tokens.add(new PostgresCatalogToken(Type.QUOTED_IDENTIFIER, query.substring(i + 1, end)));
        i = end + 1;
        continue;
      }

      // "quoted identifier", with "" as the embedded quote
      if (c == '"') {
        final StringBuilder value = new StringBuilder();
        ++i;
        boolean closed = false;
        while (i < length) {
          final char ch = query.charAt(i);
          if (ch == '"') {
            if (i + 1 < length && query.charAt(i + 1) == '"') {
              value.append('"');
              i += 2;
              continue;
            }
            ++i;
            closed = true;
            break;
          }
          value.append(ch);
          ++i;
        }
        if (!closed)
          return null;
        tokens.add(new PostgresCatalogToken(Type.QUOTED_IDENTIFIER, value.toString()));
        continue;
      }

      // $1 and friends: a parameter placeholder, which no emulated catalog query can be answered without
      // the parameter itself, so it is left as a symbol the parser will refuse.
      if (c == '$') {
        int j = i + 1;
        while (j < length && Character.isDigit(query.charAt(j)))
          ++j;
        tokens.add(new PostgresCatalogToken(Type.SYMBOL, query.substring(i, j)));
        i = j;
        continue;
      }

      if (Character.isDigit(c)) {
        int j = i;
        while (j < length && (Character.isDigit(query.charAt(j)) || query.charAt(j) == '.'))
          ++j;
        if (j < length && (query.charAt(j) == 'e' || query.charAt(j) == 'E')) {
          int k = j + 1;
          if (k < length && (query.charAt(k) == '+' || query.charAt(k) == '-'))
            ++k;
          if (k < length && Character.isDigit(query.charAt(k))) {
            j = k;
            while (j < length && Character.isDigit(query.charAt(j)))
              ++j;
          }
        }
        tokens.add(new PostgresCatalogToken(Type.NUMBER, query.substring(i, j)));
        i = j;
        continue;
      }

      if (Character.isLetter(c) || c == '_') {
        int j = i;
        while (j < length && (Character.isLetterOrDigit(query.charAt(j)) || query.charAt(j) == '_' || query.charAt(j) == '$'))
          ++j;
        tokens.add(new PostgresCatalogToken(Type.IDENTIFIER, query.substring(i, j)));
        i = j;
        continue;
      }

      // Multi-character operators first, so that "<=" is one token and not two.
      final String twoOrThree = threeCharOperator(query, i);
      if (twoOrThree != null) {
        tokens.add(new PostgresCatalogToken(Type.SYMBOL, twoOrThree));
        i += twoOrThree.length();
        continue;
      }

      tokens.add(new PostgresCatalogToken(Type.SYMBOL, String.valueOf(c)));
      ++i;
    }

    return tokens;
  }

@Override
  public TypeIndex create() {
    database.checkPermissionsOnDatabase(SecurityDatabaseUser.DATABASE_ACCESS.UPDATE_SCHEMA);

    // Checked before the existing-index lookup below, which needs the requested index type to decide whether an index
    // already on those properties covers the request.
    if (indexType == null)
      throw new DatabaseMetadataException(
          "Cannot create index on type '" + metadata.typeName + "' because indexType was not specified");

    // The index is built by SCANNING the buckets, so everything the async executor has been asked to write has to be
    // committed first, or the build simply does not see it and the records end up with no entry at all - a silent
    // wrong answer on every lookup, not a slow one (issue #6281).
    //
    // This used to be `while (database.isAsyncProcessing()) waitCompletion()`, which is not the same barrier: that
    // predicate reports queued and executing TASKS, while a worker holds ONE transaction open across up to
    // ASYNC_TX_BATCH_SIZE (10240 by default) of them. An executor whose queues happen to be drained at the instant of
    // the check therefore answers "idle" while still sitting on thousands of uncommitted records, and the guard was
    // then skipped entirely. It also prevents the NeedRetryException a running compaction used to raise when several
    // indexes are created in a row on a large dataset, which is what the guard was originally added for.
    database.waitForAsyncCompletion();

    // Carry the user-supplied TypeIndex name (set via {@link #withIndexName}) onto the
    // IndexMetadata so it propagates to each per-bucket index and ultimately to
    // {@link LocalDocumentType#addIndexInternal} which reads it when minting the TypeIndex.
    // Without this hop the manual name is dropped and the auto-derived
    // typeName + "[propertyNames]" form is used (issue #4139).
    if (indexName != null && !indexName.isEmpty())
      metadata.typeIndexName = indexName;

    final LocalSchema schema = database.getSchema().getEmbedded();

    final LocalDocumentType type = schema.getType(metadata.typeName);
    // First try the type's own index (no hierarchy walk), then fall back to the polymorphic walk so an index the type
    // only inherits is found too. Either way the outcome below is the same: it is used to answer the request, never
    // to make room for it.
    TypeIndex existingTypeIndex = type.getIndexByProperties(metadata.propertyNames);
    if (existingTypeIndex == null)
      existingTypeIndex = type.getPolymorphicIndexByProperties(metadata.propertyNames);

    // Non-null only on the replacement path below: the definition to put back if the new index cannot be built.
    ReplacedIndexDefinition replaced = null;

    if (existingTypeIndex != null) {
      // "Ignore if exists" means the caller can live with what is already there - but only when what is already there
      // provides what was asked for. A mismatch used to DROP the existing index and rebuild it with the requested
      // definition: on an inherited index that wiped the parent type's index and left an orphan entry in the schema
      // JSON (issue #4083), and on the type's own index it threw away a working index for a rebuild the stored data
      // may not even allow, leaving the type with none at all (issue #5675). Only an explicit
      // {@link #withReplaceIfIncompatible} takes an index away now, and it puts it back on failure.
      //
      // Two halves to "provides what was asked for": the structural definition (kind, uniqueness) and, when the
      // statement carried a METADATA clause, the settings that clause NAMED. The second half is skipped entirely for
      // a request that named nothing, so a guarded statement without METADATA behaves exactly as before. The
      // structural check runs first because it is the cheap one and because comparing the settings of two different
      // index KINDS would be comparing key spaces that have nothing to do with each other.
      boolean satisfied = satisfiesRequest(existingTypeIndex, indexType, unique);

      //
      // Not wrapped the way the SQL shortcut wraps its own call: reading the clause here CANNOT fail on any path that
      // sets {@link #withUserMetadata} the way it is meant to be set. The clause is read once by
      // {@code withMetadata(JSONObject)} first, which is where an unreadable value is reported - the SQL branches do
      // both inside one try, so the statement never reaches create() with a clause that would raise. A caller that
      // sets the user clause WITHOUT the parsed one has skipped that validation, and gets the reader's own message
      // here instead of a friendlier one; there is no such caller, and inventing a second error path for it would
      // only re-type an exception the reader already words correctly.
      List<String> settingMismatches = List.of();
      if (satisfied) {
        settingMismatches = findUnsatisfiedSettings(existingTypeIndex, userMetadata, indexType);
        satisfied = settingMismatches.isEmpty();
      }

      // Third half, once the definition lines up: the NAME the caller wrote. A name is not a label on the request -
      // an index is reachable only through it (SEARCH_INDEX('<name>', ...), DROP INDEX, REBUILD INDEX) - so an index
      // already on these properties under a different name does not provide what was asked for either, and a type
      // holds one index per property set so the requested name cannot be added next to it. Answering the guard with
      // the other index left the requested name uncreated while the statement reported on the request, and every
      // later lookup through that name failed (issue #6921).
      //
      // Last of the three on purpose: a definition mismatch is the harder problem and stays the reported one, so a
      // named request over an index of the wrong kind or configuration still names the kind or the settings rather
      // than the name. And only a name the caller WROTE reaches this - {@link CreateIndexStatement} forwards the
      // manual name alone and leaves the auto-derived typeName[properties] form out - which keeps a guarded request
      // that named nothing the plain no-op it has always been.
      //
      // Applied on the unguarded path too: a name conflict is not something IF NOT EXISTS makes idempotent, so the
      // "use IF NOT EXISTS" hint the unguarded message below ends with would be the wrong advice here.
      //
      // The other production caller that sets a name on a TYPE index is {@code RebuildIndexStatement}, which carries
      // the logical index's own name across the rebuild (issue #5791). It never meets this check: it drops the index
      // first, inside the same {@code executeLockingFiles} closure, so the lookup above finds nothing on those
      // properties by the time create() runs. The one shape that still reaches here - a type whose OWN index was just
      // dropped while a parent type indexes the same properties - was already refused before this check existed, by
      // the unguarded branch further down; only the message it is refused with changes.
      if (satisfied && indexName != null && !indexName.isEmpty() && !indexName.equals(existingTypeIndex.getName()))
        throw conflictWithExistingIndexName(existingTypeIndex, indexName, metadata.typeName, metadata.propertyNames);

      if (satisfied && ignoreIfExists)
        return existingTypeIndex;

      if (!satisfied && replaceIfIncompatible && existingTypeIndex.getTypeName().equals(metadata.typeName))
        // Own index, and the caller explicitly asked to replace what does not fit. Recorded here and dropped further
        // down, once everything that could still refuse the request has had its say.
        replaced = ReplacedIndexDefinition.of(existingTypeIndex);
      else if (!satisfied && (ignoreIfExists || replaceIfIncompatible))
        throw conflictWithExistingIndex(existingTypeIndex, indexType, unique, metadata.typeName, metadata.propertyNames,
            settingMismatches);
      else
        // Reached when the request was NOT guarded, whether or not the existing index satisfies it. The suffix names
        // the guard that makes the statement idempotent: the satisfied case here is a caller asking twice for
        // something already there - a Cypher CREATE CONSTRAINT without IF NOT EXISTS over its own unique index, say -
        // and the bare sentence left them to work out that the guard was the missing piece. The sentence itself is
        // unchanged: it is long-standing wording that callers may already match on.
        throw new IllegalArgumentException(
            "Found the existent index '" + existingTypeIndex.getName() + "' defined on the properties '" + Arrays.asList(
                metadata.propertyNames) + "' for type '" + metadata.typeName + "'" + (satisfied ?
                ". It already provides what was requested: use IF NOT EXISTS to make this statement idempotent" :
                ". Drop it first if the definition has to change"));
    }

    if (metadata.propertyNames.isEmpty())
      throw new DatabaseMetadataException(
          "Cannot create index on type '" + metadata.typeName + "' because there are no property defined");

    // CHECK ALL THE PROPERTIES EXIST
    final Type[] keyTypes = new Type[metadata.propertyNames.size()];
    int i = 0;

    for (final String propertyName : metadata.propertyNames) {
      if (type instanceof LocalEdgeType && ("@out".equals(propertyName) || "@in".equals(propertyName))) {
        keyTypes[i++] = Type.LINK;
      } else {
        // Check for the "by item" (LIST) / "by key" / "by value" (MAP) modifiers
        String actualPropertyName = propertyName;
        boolean isByItem = false;
        boolean isByKey = false;
        boolean isByValue = false;

        if (propertyName.endsWith(" by item")) {
          isByItem = true;
          actualPropertyName = propertyName.substring(0, propertyName.length() - 8);
        } else if (propertyName.endsWith(" by key")) {
          isByKey = true;
          actualPropertyName = propertyName.substring(0, propertyName.length() - 7);
        } else if (propertyName.endsWith(" by value")) {
          isByValue = true;
          actualPropertyName = propertyName.substring(0, propertyName.length() - 9);
        }

        // First, try to find the property with the exact name (handles properties with dots in their names)
        Property property = type.getPolymorphicPropertyIfExists(actualPropertyName);

        if (property == null && actualPropertyName.contains(".")) {
          // Property with exact name doesn't exist, check if this could be a nested path
          final String[] pathParts = actualPropertyName.split("\\.", 2); // Split into at most 2 parts
          final String rootPropertyName = pathParts[0];

          // Try to find the root property
          property = type.getPolymorphicPropertyIfExists(rootPropertyName);

          if (property != null) {
            // Found root property - this is a nested path
            // For nested paths with BY ITEM, the root must be a LIST
            if (isByItem && property.getType() != Type.LIST) {
              throw new SchemaException(
                  "Cannot create index with BY ITEM on nested property path '" + metadata.typeName + "." + actualPropertyName
                      + "' because the root property '" + rootPropertyName + "' is not a LIST type (found: " + property.getType()
                      + ")");
            }

            // For nested properties, we'll use STRING as the key type since we can't validate the nested structure at schema definition time
            // The actual type will be determined at runtime during indexing
            keyTypes[i++] = Type.STRING;
            continue;
          }
        }

        // If we still don't have a property, it doesn't exist
        if (property == null) {
          if (defaultKeyTypesForUndeclaredProperties != null && i < defaultKeyTypesForUndeclaredProperties.length
              && defaultKeyTypesForUndeclaredProperties[i] != null) {
            // Caller (e.g. OpenCypher CREATE INDEX) opted into keeping the property undeclared so
            // writes preserve their original Java type. The index keys are serialised using this
            // fall-back Type via the usual Type.convert path.
            keyTypes[i] = defaultKeyTypesForUndeclaredProperties[i];
            i++;
            continue;
          }
          throw new SchemaException(
              "Cannot create the index on type '" + metadata.typeName + "." + actualPropertyName
                  + "' because the property does not exist");
        }

        // Validate BY ITEM is only used with LIST type
        if (isByItem && property.getType() != Type.LIST) {
          throw new SchemaException("Cannot create index with BY ITEM on property '" + metadata.typeName + "." + actualPropertyName
              + "' because it is not a LIST type (found: " + property.getType() + ")");
        }

        // Validate BY KEY / BY VALUE are only used with MAP type
        if ((isByKey || isByValue) && property.getType() != Type.MAP) {
          throw new SchemaException(
              "Cannot create index with BY " + (isByKey ? "KEY" : "VALUE") + " on property '" + metadata.typeName + "."
                  + actualPropertyName + "' because it is not a MAP type (found: " + property.getType() + ")");
        }

        if (isByItem) {
          // For BY ITEM on LIST, the key type should be STRING (since list items are indexed individually).
          // Lists can contain heterogeneous types, so we use STRING as a generic type for list items
          keyTypes[i++] = Type.STRING;
        } else if (isByKey) {
          // MAP keys are strings
          keyTypes[i++] = Type.STRING;
        } else if (isByValue) {
          // MAP values use the declared "OF" sub-type when available, otherwise fall back to STRING
          final String ofType = property.getOfType();
          final Type valueType = ofType != null ? Type.getTypeByName(ofType) : null;
          keyTypes[i++] = valueType != null ? valueType : Type.STRING;
        } else {
          keyTypes[i++] = property.getType();
        }
      }
    }

    final List<Bucket> buckets = type.getBuckets(true);
    final Index[] indexes = new Index[buckets.size()];
    final boolean sortedBuild = buildMode == IndexBuildMode.SORTED;
    final SortedIndexBuildRecoveryMarker[] recoveryMarker = new SortedIndexBuildRecoveryMarker[1];
    final SortedIndexBuildMetrics[] sortedBuildMetrics = new SortedIndexBuildMetrics[1];
    final long sortedBuildStarted = sortedBuild ? System.nanoTime() : 0L;

    if (sortedBuild)
      validateSortedBuildPreconditions();

    // Last thing before the build: everything above can still refuse the request (an undeclared property, a BY ITEM on
    // a non-LIST, a sorted build on a replicated database), and none of those refusals may cost the caller the index it
    // already had.
    //
    // NOT ATOMIC, and deliberately so. The drop is its own committed schema change - LocalSchema.dropIndex wraps itself
    // in recordFileChanges, and so does the build below - so the two cannot be rolled back as one. The window is
    // covered for a FAILING build (restoreReplacedIndex in the catch arms below) but not for a process that dies inside
    // it: the type then reopens with no index on those properties and has to be given one again. Making it atomic means
    // holding a schema transaction across a full index build, which is the wrong trade for a DDL statement that already
    // rebuilds every entry. Narrowing it further would mean building the new index alongside the old one, which
    // LocalDocumentType.indexesByProperties cannot represent - one index per property set is the invariant.
    //
    // Only an explicit withReplaceIfIncompatible reaches here, so nothing is exposed to this window without asking.
    if (replaced != null)
      existingTypeIndex.drop();

    // Asked here because below this line there is ALWAYS a transaction, and the answer is about the one that was
    // already there (issue #6324, item 1). See IndexBuilder#buildSharesCallerTransaction.
    final boolean sharesCallerTransaction = buildSharesCallerTransaction();

    final TypeIndex created;
    // The barrier of #6281, paid at the top of this method, covers what the async side wrote BEFORE the build. This
    // covers what it would write DURING it (issue #6303, item 2), and only the first half was ever here:
    // LocalDocumentType.addIndexInternal registers the index before the scan, so a record saved AFTER that point
    // stages its own entry and is safe - but one saved in the window between the barrier and that registration, and
    // still uncommitted when the scan reads, is in neither the scan nor the index. Nothing stopped an async worker
    // from opening exactly that window, because unlike BucketIndexBuilder this path never parked the workers at all.
    //
    // Held across the whole build rather than only across the scan: the registration is what the window is measured
    // from, and it happens inside recordFileChanges. Reentrant, so the nested quiescence of any builder reached from
    // here simply rides on this one.
    try (final AsyncQuiesce asyncPaused = database.quiesceAsync()) {
      final long recordFileChangesStarted = System.nanoTime();
      schema.recordFileChanges(() -> {
        if (sortedBuild) {
          recoveryMarker[0] = SortedIndexBuildRecoveryMarker.create(database, metadata.typeName, metadata.propertyNames,
              buildSpillDirectory);
          sortedBuildMetrics[0] = createWithSortedBuild(schema, type, keyTypes, buckets, indexes, recoveryMarker[0]);
        } else
          for (int idx = 0; idx < buckets.size(); ++idx) {
            final int finalIdx = idx;

            if (!sharesCallerTransaction) {
              // ONE TRANSACTION, exactly as before issue #6324: with nothing of anybody else's to see, creating and
              // building in one go is both simpler and one commit per bucket cheaper.
              database.transaction(() -> {

                final LocalBucket bucket = (LocalBucket) buckets.get(finalIdx);

                indexes[finalIdx] = createBucketIndex(schema, type, keyTypes, bucket, true);

              }, false, maxAttempts, null, null);
              continue;
            }

            // TWO TRANSACTIONS, and the split is the whole of issue #6324, item 1.
            //
            // The COMPONENT is created in a transaction of its OWN. recordFileChanges writes the schema entry that
            // names this index as soon as this callback returns, whatever the caller's transaction goes on to do, so
            // the index FILE has to be committed on the same terms: leaving its first page inside a caller's
            // transaction that later rolls back would leave the schema pointing at a file with no pages, which fails
            // on the next write with "the file is invalid". Committing it also keeps the index usable from a NESTED
            // transaction, which cannot see an outer transaction's uncommitted pages.
            database.transaction(() -> {

              final LocalBucket bucket = (LocalBucket) buckets.get(finalIdx);

              indexes[finalIdx] = createBucketIndex(schema, type, keyTypes, bucket, false);

            }, false, maxAttempts, null, null);

            // The BUILD then joins the caller's transaction, because a scan reads the transaction it runs in: the
            // pages that transaction has modified first, the committed ones underneath. That is what lets it see
            // records the caller has written and not yet committed - `INSERT INTO V SET id = 7;
            // CREATE INDEX ON V (id)` in one transaction used to end with the record present and NO entry for it, in
            // neither the scan nor the index - and it makes the entries commit, or roll back, with the records they
            // describe.
            database.transaction(() -> buildCreatedIndex(indexes[finalIdx], true), true, maxAttempts, null, null);
          }

        return null;
      }, sortedBuild);
      final long recordFileChangesNanos = System.nanoTime() - recordFileChangesStarted;

      long cleanupNanos = 0L;
      if (recoveryMarker[0] != null) {
        final long cleanupStarted = System.nanoTime();
        recoveryMarker[0].clear();
        cleanupNanos = System.nanoTime() - cleanupStarted;
      }

      if (sortedBuildMetrics[0] != null) {
        final SortedIndexBuildMetrics completed = sortedBuildMetrics[0].completed(
            Math.max(0L, recordFileChangesNanos - sortedBuildMetrics[0].pipelineNanos()), cleanupNanos,
            System.nanoTime() - sortedBuildStarted);
        emitSortedBuildMetrics(completed);
      }

      created = type.getIndexByProperties(metadata.propertyNames);
    } catch (final NeedRetryException e) {
      if (cleanupIndexes(schema, indexes, e)
          && (recoveryMarker[0] == null || recoveryMarker[0].baselineRestored(database)))
        clearRecoveryMarker(recoveryMarker[0], e);
      restoreReplacedIndex(replaced, e);
      throw e;
    } catch (final Throwable e) {
      if (cleanupIndexes(schema, indexes, e)
          && (recoveryMarker[0] == null || recoveryMarker[0].baselineRestored(database)))
        clearRecoveryMarker(recoveryMarker[0], e);
      restoreReplacedIndex(replaced, e);
      // Carry the root cause into the message: this exception is what the SQL/HTTP layers report back, and
      // without the reason a configuration mistake (a missing vector 'dimensions', an incompatible property
      // type, ...) reaches the user as a bare "Error on creating index" with nowhere to go (issue #5607).
      throw new IndexException("Error on creating index on type '" + metadata.typeName + "', properties " + metadata.propertyNames
          + (e.getMessage() != null ? ": " + e.getMessage() : ""), e);
    }

    // An index is half of what decides whether a partition is any use, so one created after the strategy was assigned
    // can undo the check that accepted it: recollating the partition index COLLATE CI makes it unprunable, and an
    // index on other properties adds a lookup that fans out (issue #5637). Reported from here rather than from
    // LocalDocumentType.addIndexInternal, which runs once per BUCKET and also during schema reload, so the same lines
    // would be multiplied by the bucket count and repeated on every open.
    //
    // Never refuses, unlike the identical diagnosis at assignment time: there the strategy was what the user asked
    // for and a blocked one is pure cost, whereas here the INDEX is what was asked for and it is useful, so the
    // partitioning is what gives way. Outside the try/catch above on purpose - a diagnostic must not be able to undo
    // an index that was built successfully by falling into the cleanup arm.
    try {
      type.reportPartitionSuitabilityAfterSchemaChange();
    } catch (final RuntimeException e) {
      // Same reasoning one step further. By this point the index is built, committed and registered on the type, so
      // letting anything unexpected out of the diagnosis would fail the command over an index that exists - and the
      // obvious retry then fails again with "already exists". SCHEMA_CHANGE mode cannot raise the refusal, so this
      // only catches a genuine fault in the check or the logging, which is worth a line and nothing more.
      LogManager.instance().log(this, Level.WARNING,
          "Cannot report the partition suitability of type '%s' after creating the index on %s. The index itself was "
              + "created successfully", e, metadata.typeName, metadata.propertyNames);
    }

    return created;
  }

