@Override
  public ParsedLine parse(final String line, final int cursor, final ParseContext context) {
    if (line == null)
      return null;

    final List<String> words = new LinkedList();
    final StringBuilder current = new StringBuilder();
    int wordCursor = -1;
    int wordIndex = -1;
    int quoteStart = -1;
    int rawWordCursor = -1;
    int rawWordLength = -1;
    int rawWordStart = 0;
    int braceDepth = 0;
    int openBraceOffset = -1;
    boolean insideLineComment = false;
    boolean insideBlockComment = false;

    for (int i = 0; i < line.length(); ++i) {
      if (i == cursor) {
        wordIndex = words.size();
        wordCursor = current.length();
        rawWordCursor = i - rawWordStart;
      }

      final char c = line.charAt(i);

      if (insideLineComment) {
        // KEEP THE LINE TERMINATOR SO THE FOLLOWING TEXT IS NOT GLUED TO THE COMMANDED LINE
        if (c == '\n' || c == '\r') {
          insideLineComment = false;
          current.append(c);
        }
      } else if (insideBlockComment) {
        if (c == '*' && i + 1 < line.length() && line.charAt(i + 1) == '/') {
          insideBlockComment = false;
          ++i;
        }
      } else if (quoteStart < 0 && isLineCommentStart(line, i)) {
        insideLineComment = true;
        ++i;
      } else if (quoteStart < 0 && isBlockCommentStart(line, i)) {
        insideBlockComment = true;
        ++i;
      } else if (quoteStart < 0 && this.isQuoteChar(line, i)) {
        quoteStart = i;
        current.append(c);
      } else if (quoteStart >= 0) {
        if (line.charAt(quoteStart) == c && !this.isEscaped(line, i)) {
          current.append(c);
          quoteStart = -1;
          if (rawWordCursor >= 0 && rawWordLength < 0) {
            rawWordLength = i - rawWordStart + 1;
          }
        } else {
          // THE ESCAPE CHARACTER IS KEPT: IT IS PART OF THE TEXT HANDED TO THE QUERY ENGINE, WHICH OWNS STRING-LITERAL
          // ESCAPING. isEscaped() ABOVE ALREADY STOPPED THE ESCAPED QUOTE FROM CLOSING THE STRING (ISSUE #6827)
          current.append(c);
        }
      } else if (this.isDelimiter(line, i) && braceDepth == 0) {
        if (current.length() > 0) {
          words.add(current.toString());
          current.setLength(0);
          if (rawWordCursor >= 0 && rawWordLength < 0) {
            rawWordLength = i - rawWordStart;
          }
        }

        rawWordStart = i + 1;
      } else {
        if (c == '{') {
          if (braceDepth == 0)
            openBraceOffset = i;
          braceDepth++;
          current.append(c);
        } else if (c == '}') {
          final int prevDepth = braceDepth;
          // A CLOSING BRACE WITH NOTHING OPEN IS JUST TEXT: LETTING THE DEPTH GO NEGATIVE WOULD STOP EVERY FOLLOWING SEMICOLON
          // FROM SEPARATING THE COMMANDS FOR THE REST OF THE TEXT (ISSUE #6392)
          if (braceDepth > 0)
            braceDepth--;
          if (braceDepth == 0)
            openBraceOffset = -1;
          current.append(c);

          // Check if we just closed all braces and there's more content after newlines
          if (prevDepth == 1 && braceDepth == 0 && current.length() > 0) {
            // Look ahead to see if there's a newline followed by non-whitespace content
            int j = i + 1;
            boolean foundNewline = false;
            boolean foundContent = false;

            while (j < line.length() && Character.isWhitespace(line.charAt(j))) {
              if (line.charAt(j) == '\n' || line.charAt(j) == '\r') {
                foundNewline = true;
              }
              j++;
            }

            if (j < line.length() && !this.isDelimiter(line, j)) {
              foundContent = true;
            }

            // If we found a newline and then more content (not a semicolon), split here
            if (foundNewline && foundContent) {
              words.add(current.toString());
              current.setLength(0);
              if (rawWordCursor >= 0 && rawWordLength < 0) {
                rawWordLength = i - rawWordStart + 1;
              }
              rawWordStart = j;
              i = j - 1; // Will be incremented by the loop
            }
          }
        } else {
          current.append(c);
        }
      }
    }

    blockCommentOpen = insideBlockComment;
    unbalancedBraceOffset = braceDepth > 0 ? openBraceOffset : -1;

    if (current.length() > 0 || cursor == line.length()) {
      words.add(current.toString());
      if (rawWordCursor >= 0 && rawWordLength < 0) {
        rawWordLength = line.length() - rawWordStart;
      }
    }

    if (cursor == line.length()) {
      wordIndex = words.size() - 1;
      wordCursor = words.getLast().length();
      rawWordCursor = cursor - rawWordStart;
      rawWordLength = rawWordCursor;
    }

    final String openingQuote = quoteStart >= 0 ? line.substring(quoteStart, quoteStart + 1) : null;
    return new DefaultParser.ArgumentList(line, words, wordIndex, wordCursor, cursor, openingQuote, rawWordCursor, rawWordLength);
  }

public MultiColumnAggregationResult aggregateMulti(final long fromTs, final long toTs,
      final List<MultiColumnAggregationRequest> requests, final long bucketIntervalMs,
      final TagFilter tagFilter, final AggregationMetrics metrics) throws IOException {
    final int reqCount = requests.size();

    // Determine actual data range to size flat arrays correctly.
    //
    // This scan runs WITHOUT the per-shard compaction read locks on purpose - they are acquired further
    // down, around the reads that actually produce the numbers. A compaction, or a fresh append, can
    // therefore slip in between the estimate and the reads. That is deliberate and safe: the estimate
    // only decides how wide the flat window is, and MultiColumnAggregationResult parks anything landing
    // outside it in its overflow map rather than dropping it (issue #6937). Taking the locks here would
    // hold them across the whole aggregation for no correctness gain, just contention with the writers.
    long actualMin = Long.MAX_VALUE;
    long actualMax = Long.MIN_VALUE;
    final boolean useFlatMode = bucketIntervalMs > 0;
    if (useFlatMode) {
      for (final TimeSeriesShard shard : shards) {
        final TimeSeriesSealedStore ss = shard.getSealedStore();
        if (ss.getBlockCount() > 0) {
          if (ss.getGlobalMinTimestamp() < actualMin)
            actualMin = ss.getGlobalMinTimestamp();
          if (ss.getGlobalMaxTimestamp() > actualMax)
            actualMax = ss.getGlobalMaxTimestamp();
        }

        // The mutable bucket carries everything appended since the last compaction and is NOT bounded
        // by the sealed range - compaction is driven by the maintenance scheduler, not by sample
        // timestamps, so the un-sealed tail can span an arbitrary number of buckets. Sizing the flat
        // array from the sealed stores alone made every sample past that range resolve to an
        // out-of-range index and vanish without an error (issue #6937).
        // One header-page read for the pair, so the two bounds are a consistent snapshot.
        final long[] mutableRange = shard.getMutableBucket().getMinMaxTimestamps();
        // Empty markers are Long.MAX_VALUE / Long.MIN_VALUE, so an empty bucket never widens anything.
        if (mutableRange[0] <= mutableRange[1]) {
          if (mutableRange[0] < actualMin)
            actualMin = mutableRange[0];
          if (mutableRange[1] > actualMax)
            actualMax = mutableRange[1];
        }
      }
      // Clamp to query range
      if (fromTs != Long.MIN_VALUE && fromTs > actualMin)
        actualMin = fromTs;
      if (toTs != Long.MAX_VALUE && toTs < actualMax)
        actualMax = toTs;
    }

    final long firstBucket;
    final int maxBuckets;
    if (useFlatMode && actualMin <= actualMax) {
      firstBucket = Math.floorDiv(actualMin, bucketIntervalMs) * bucketIntervalMs;
      final long computedBuckets = Math.floorDiv(actualMax - firstBucket, bucketIntervalMs) + 2;
      if (computedBuckets > MultiColumnAggregationResult.MAX_FLAT_BUCKETS)
        // Will trigger map-mode fallback in MultiColumnAggregationResult constructor
        maxBuckets = MultiColumnAggregationResult.MAX_FLAT_BUCKETS + 1;
      else
        maxBuckets = (int) computedBuckets;
    } else {
      firstBucket = 0;
      maxBuckets = 0;
    }

    // Pre-extract column indices and types for mutable bucket iteration
    final int[] columnIndices = new int[reqCount];
    final boolean[] isCount = new boolean[reqCount];
    for (int r = 0; r < reqCount; r++) {
      columnIndices[r] = requests.get(r).columnIndex();
      isCount[r] = requests.get(r).type() == AggregationType.COUNT;
    }

    // Process sealed stores in parallel when there are multiple shards with data
    if (shardCount > 1 && maxBuckets > 0) {
      @SuppressWarnings("unchecked")
      final CompletableFuture<MultiColumnAggregationResult>[] futures = new CompletableFuture[shardCount];

      // Acquire all shard compaction read locks on the calling thread (which has the database
      // transaction context) before dispatching futures. This prevents compaction from
      // completing between the sealed reads (in futures) and the mutable reads (on the calling
      // thread), which would cause data loss: sealed would see the old state and mutable would
      // be empty after compaction cleared it.
      // Worker threads only read sealed stores (no transaction required); mutable reads happen
      // on the calling thread after futures complete.
      for (int s = 0; s < shardCount; s++)
        shards[s].getCompactionLock().readLock().lock();
      try {
        final AggregationMetrics[] shardMetricsArr = metrics != null ? new AggregationMetrics[shardCount] : null;
        for (int s = 0; s < shardCount; s++) {
          final TimeSeriesShard shard = shards[s];
          final AggregationMetrics shardMetrics = metrics != null ? new AggregationMetrics() : null;
          if (shardMetricsArr != null)
            shardMetricsArr[s] = shardMetrics;
          futures[s] = CompletableFuture.supplyAsync(() -> {
            try {
              final MultiColumnAggregationResult shardResult =
                  new MultiColumnAggregationResult(requests, firstBucket, bucketIntervalMs, maxBuckets);
              shard.getSealedStore().aggregateMultiBlocks(fromTs, toTs, requests, bucketIntervalMs, shardResult, shardMetrics, tagFilter);
              return shardResult;
            } catch (final IOException e) {
              throw new CompletionException(e);
            }
          }, shardExecutor);
        }

        // Wait for all sealed reads to complete
        try {
          CompletableFuture.allOf(futures).join();
        } catch (final CompletionException e) {
          if (e.getCause() instanceof IOException ioe)
            throw ioe;
          throw new IOException("Parallel shard aggregation failed", e.getCause());
        }

        // Merge metrics after all futures have completed (avoids race condition)
        if (shardMetricsArr != null)
          for (final AggregationMetrics sm : shardMetricsArr)
            metrics.mergeFrom(sm);

        final MultiColumnAggregationResult result = futures[0].join();
        for (int s = 1; s < shardCount; s++)
          result.mergeFrom(futures[s].join());

        // Process mutable buckets on the calling thread (has both transaction context and the
        // compaction read locks acquired above, so compaction cannot clear mutable data now)
        final double[] rowValues = new double[reqCount];
        for (final TimeSeriesShard shard : shards) {
          final Iterator<Object[]> mutableIter = shard.getMutableBucket().iterateRange(fromTs, toTs, null);
          while (mutableIter.hasNext()) {
            final Object[] row = mutableIter.next();
            if (tagFilter != null && !tagFilter.matches(row))
              continue;
            final long ts = (long) row[0];
            final long bucketTs = Math.floorDiv(ts, bucketIntervalMs) * bucketIntervalMs;
            for (int r = 0; r < reqCount; r++) {
              if (isCount[r])
                rowValues[r] = 1.0;
              else if (columnIndices[r] < row.length && row[columnIndices[r]] instanceof Number n)
                rowValues[r] = n.doubleValue();
              else
                rowValues[r] = 0.0;
            }
            result.accumulateRow(bucketTs, rowValues);
          }
        }

        result.finalizeAvg();
        if (metrics != null)
          metrics.addOverflowBuckets(result.getOverflowBucketCount());
        return result;
      } finally {
        for (int s = 0; s < shardCount; s++)
          shards[s].getCompactionLock().readLock().unlock();
      }

    } else {
      // Sequential path: single shard or no flat mode
      final MultiColumnAggregationResult result = maxBuckets > 0
          ? new MultiColumnAggregationResult(requests, firstBucket, bucketIntervalMs, maxBuckets)
          : new MultiColumnAggregationResult(requests);

      final double[] rowValues = new double[reqCount];

      final long singleBucketTs = singleBucketAnchor(fromTs);

      for (final TimeSeriesShard shard : shards) {
        // Hold the compaction read lock for sealed+mutable reads to prevent data loss
        // if compaction completes between reading the two layers.
        shard.getCompactionLock().readLock().lock();
        try {
          shard.getSealedStore().aggregateMultiBlocks(fromTs, toTs, requests, bucketIntervalMs, result, metrics, tagFilter);

          final Iterator<Object[]> mutableIter = shard.getMutableBucket().iterateRange(fromTs, toTs, null);
          while (mutableIter.hasNext()) {
            final Object[] row = mutableIter.next();
            if (tagFilter != null && !tagFilter.matches(row))
              continue;
            final long ts = (long) row[0];
            final long bucketTs = bucketIntervalMs > 0 ? Math.floorDiv(ts, bucketIntervalMs) * bucketIntervalMs : singleBucketTs;

            for (int r = 0; r < reqCount; r++) {
              if (isCount[r])
                rowValues[r] = 1.0;
              else if (columnIndices[r] < row.length && row[columnIndices[r]] instanceof Number n)
                rowValues[r] = n.doubleValue();
              else
                rowValues[r] = 0.0;
            }

            result.accumulateRow(bucketTs, rowValues);
          }
        } finally {
          shard.getCompactionLock().readLock().unlock();
        }
      }

      result.finalizeAvg();
      if (metrics != null)
        metrics.addOverflowBuckets(result.getOverflowBucketCount());
      return result;
    }
  }

