public TimeSeriesEngine(final DatabaseInternal database, final String typeName,
      final List<ColumnDefinition> columns, final int shardCount,
      final long compactionBucketIntervalMs, final int mutableFormatVersion) throws IOException {
    this.database = database;
    this.typeName = typeName;
    this.columns = columns;
    this.columnKinds = ObjectColumnsRowSource.kindsOf(columns);
    this.shardCount = shardCount;
    this.compactionBucketIntervalMs = compactionBucketIntervalMs;
    this.shards = new TimeSeriesShard[shardCount];
    final AtomicInteger threadCounter = new AtomicInteger(0);
    this.shardExecutor = Executors.newFixedThreadPool(shardCount, r -> {
      final Thread t = new Thread(r, "ArcadeDB-TS-Shard-" + typeName + "-" + threadCounter.getAndIncrement());
      t.setDaemon(true);
      return t;
    });

    try {
      // One dictionary per type, resolved before the shards so every shard shares the same id space.
      this.tagDictionary = TimeSeriesTagDictionary.openOrCreate(database, typeName, columns, mutableFormatVersion);
      for (int i = 0; i < shardCount; i++)
        shards[i] = new TimeSeriesShard(database, typeName, i, columns, compactionBucketIntervalMs, tagDictionary);
    } catch (final Exception e) {
      shardExecutor.shutdownNow();
      // Release the shards that were successfully created - their sealed stores only, NOT their mutable buckets.
      // A full close() here made a corrupt .ts.sealed on shard N take the mutable buckets of shards 0..N-1 down
      // with it, permanently: those buckets are registered with the schema, which owns closing them, and
      // PaginatedComponentFile.close() sets open=false so its own lazy reopen refuses ever after. That left
      // initEngine() unretryable for any type with more than one shard, so the whole recovery path added for
      // issue #6839 would have worked for SHARDS 1 and silently not above it.
      for (final TimeSeriesShard shard : shards) {
        if (shard != null) {
          try {
            shard.closeAfterFailedInit();
          } catch (final IOException ignored) {
          }
        }
      }
      throw e instanceof IOException ? (IOException) e : new IOException("Failed to initialize shards for " + typeName, e);
    }
  }

