@Override
  public ExecutionResponse execute(final HttpServerExchange exchange, final ServerSecurityUser user, final Database database,
      final JSONObject json)
      throws IOException {
    if (json == null)
      return new ExecutionResponse(400, "{ \"error\" : \"Command text is null\"}");

    final QueryProfile profile = new QueryProfile();
    QueryProfile.pushCurrent(profile);
    try {

    // Issue #3864 follow-up: use the optimized toMap so JSON numeric arrays (e.g. vector
    // embeddings inside `params.batch[*].vector`) are returned as primitive double[]/long[]
    // instead of List<Double>, avoiding millions of boxed Number allocations per request.
    final long deserializationStart = System.nanoTime();
    final Map<String, Object> requestMap = json.toMap(true);
    profile.addDeserializationNanos(System.nanoTime() - deserializationStart);

    // No HTTP-level leader forwarding here: reads run locally on replicas, and writes are
    // forwarded at the engine level by RaftReplicatedDatabase.command() when
    // QueryEngine.isExecutedByTheLeader() or analyze(query).isDDL() is true.

    if (requestMap.get("command") == null)
      throw new IllegalArgumentException("command missing");

    final String language = requireStringField(requestMap, "language");
    // Do NOT HTML-decode the command: the command is already transported losslessly as a JSON string,
    // and a command can legitimately carry HTML entities (e.g. &quot;, &amp;) inside its data. Decoding
    // them here corrupts the payload (e.g. breaks the embedded JSON of an INSERT ... CONTENT { ... }).
    String command = requireStringField(requestMap, "command");
    final Integer requestLimit = optionalIntField(requestMap, "limit");
    final String serializer = requireStringField(requestMap, "serializer", "record");
    final String profileExecution = requireStringField(requestMap, "profileExecution", null);
    // Issue #5812: off unless the caller explicitly asks for the @props type hint on non-element rows.
    final boolean includeTypeHints = requestMap.get("typeHints") instanceof Boolean b && b;

    // Negotiated up front (issue #7306) so a request the stream cannot express is refused before the command
    // runs rather than after. A streamed response is rows and a trailer: the buffered envelope's 'explain',
    // 'explainPlan', 'stats' and 'profile' properties have nowhere to go in it, and silently dropping the one
    // the caller explicitly asked for would be worse than saying so.
    final boolean streaming = isNdJsonRequested(exchange);
    if (streaming) {
      ndJsonRowSerializer(serializer, includeTypeHints);
      if (profileExecution != null)
        throw new IllegalArgumentException("'profileExecution' reports the plan and the timings in the response "
            + "envelope, which the streaming encoding does not have: request it with 'Accept: application/json'");
    }

    if (command == null || command.isEmpty())
      return new ExecutionResponse(400, "{ \"error\" : \"Command text is null\"}");

    if (language == null || language.isEmpty())
      return new ExecutionResponse(400, "{ \"error\" : \"Language is null\"}");

    command = command.trim();

    if (streaming)
      requireStreamableStatement(database, language, command);

    final Object rawParams = requestMap.get("params");
    Map<String, Object> paramMap;
    if (rawParams instanceof Map<?, ?> m) {
      @SuppressWarnings("unchecked")
      final Map<String, Object> typed = (Map<String, Object>) m;
      paramMap = typed;
    } else if (rawParams instanceof List<?> list) {
      // Positional params forwarded as a JSON array [v0, v1, ...] — convert to ordinal map
      paramMap = new HashMap<>((int) (list.size() / 0.75f) + 1);
      for (int i = 0; i < list.size(); i++)
        paramMap.put("" + i, list.get(i));
    } else if (rawParams != null && rawParams.getClass().isArray()) {
      // Positional params converted to a primitive array by toMap(true) — convert to ordinal map
      final int len = java.lang.reflect.Array.getLength(rawParams);
      paramMap = new HashMap<>((int) (len / 0.75f) + 1);
      for (int i = 0; i < len; i++)
        paramMap.put("" + i, java.lang.reflect.Array.get(rawParams, i));
    } else {
      paramMap = new HashMap<>();
    }

    // Decode typed JSON markers ($bytes, $int8) before any transaction starts so a malformed
    // marker surfaces as a clean HTTP 400 via the IllegalArgumentException catch arm in
    // AbstractServerHttpHandler, instead of being wrapped by the surrounding TransactionException
    // and downgraded to HTTP 500.
    paramMap = AbstractQueryHandler.decodeTypedJsonMarkers(paramMap);

    // The cap used to push a LIMIT down into a command that states none: the caller's own 'limit' when
    // present, the configured default otherwise. A command that already carries a LIMIT is left untouched and
    // its own value decides the response size, resolved from the execution plan after execution.
    //
    // Bounded by the hard ceiling before it is pushed down, not only when the rows are serialized: an
    // unlimited 'limit' used to push nothing down at all, so the whole result reached the handler - and with
    // 'profileExecution: detailed' it was materialized in full by materializeResultSet before any cap could
    // look at it. With the ceiling in the pushed-down LIMIT the engine stops one row past it (issue #5719).
    // Only the caller's own value needs clamping here: getDefaultRowLimit() is already bounded by the ceiling.
    final int maxResultRows = getMaxResultRows();
    final int autoLimit = requestLimit != null ? applyMaxResultRows(requestLimit, maxResultRows) : getDefaultRowLimit();
    final boolean autoLimited = requiresAutomaticLimit(command, language, autoLimit);
    // Kept for the log: a warning must show the operator the query the caller sent, not the rewritten one.
    final String originalCommand = command;
    if (autoLimited)
      // One row above the cap: the extra row is never serialized, it only makes truncation detectable.
      command = command + " limit " + truncationProbeLimit(autoLimit);

    if ("sqlScript".equalsIgnoreCase(language) && !command.endsWith(";"))
      command += ";";

    if ("detailed".equalsIgnoreCase(profileExecution))
      paramMap.put("$profileExecution", true);

    boolean awaitResponse = true;
    if (requestMap.containsKey("awaitResponse") && requestMap.get("awaitResponse") instanceof Boolean) {
      awaitResponse = (Boolean) requestMap.get("awaitResponse");
    }

    if (!awaitResponse) {
      executeCommandAsync(database, language, command, paramMap);

      return new ExecutionResponse(202, "{ \"result\": \"Command accepted for asynchronous execution\"}");
    } else {

      final boolean detailedProfile = "detailed".equalsIgnoreCase(profileExecution);

      final long engineStart = System.nanoTime();
      ResultSet qResult = executeCommand(database, language, command, paramMap);

      try {
        final JSONObject response = new JSONObject();
        response.put("user", user != null ? user.getName() : null);

        // How many rows the response may carry, in decreasing order of explicitness: the request 'limit', the
        // LIMIT the command carries (read back from the execution plan, and ignored when it is the one this
        // handler pushed down itself), the configured default. Only the last one can drop rows the caller
        // never asked to drop, and that is exactly what 'truncated' reports below (issue #5711).
        final int planLimit = autoLimited ? 0 : getPlanLimit(qResult);
        final int limit = resolveLimit(requestLimit, planLimit);
        final SerializationOutcome outcome;

        if (streaming && qResult instanceof ExplainResultSet)
          // The same rule as the 'profileExecution' refusal above, for the spelling that carries no request
          // field: EXPLAIN returns no rows at all, so streaming it would be an empty stream that told the
          // caller nothing about the plan it asked for. Checked here because only the result set says so - the
          // statement can be nested in a script.
          throw new IllegalArgumentException("EXPLAIN produces a plan, not a row stream: request it with "
              + "'Accept: application/json'");

        if (qResult instanceof ExplainResultSet) {
          // EXPLAIN (or SQL PROFILE): extract plan, then drain the single record
          // so serializeResultSet produces an empty result structure
          final var executionPlan = qResult.getExecutionPlan().get();
          final String explainText = executionPlan.prettyPrint(0, 2);
          while (qResult.hasNext()) {
            qResult.next();
          }
          profile.addEngineNanos(System.nanoTime() - engineStart);

          final long serializationStart = System.nanoTime();
          outcome = serializeResultSetBounded(database, serializer, limit, maxResultRows, response, qResult,
              includeTypeHints);
          response.put("explain", explainText);
          response.put("explainPlan", executionPlan.toResult().toJSON());
          profile.addSerializationNanos(System.nanoTime() - serializationStart);
        } else {
          if (detailedProfile && qResult != null) {
            // Materialize the ResultSet inside the engine timer so the serialization
            // timer captures only the wire-format conversion and not query work.
            // materializeResultSet closes the source and returns a fresh in-memory ResultSet.
            //
            // Bounded by the same cap the response will honor: this is the one place that drains the whole
            // result set into memory before any cap is applied, so a command carrying its own huge LIMIT -
            // which is left as written and therefore gets no pushed-down bound - could materialize an
            // arbitrary number of rows here (issue #5719). One row above the cap, as the pushdown does, so
            // the truncation stays detectable.
            qResult = materializeResultSet(qResult, truncationProbeLimit(applyMaxResultRows(limit, maxResultRows)));
          }
          profile.addEngineNanos(System.nanoTime() - engineStart);

          final long serializationStart = System.nanoTime();
          if (streaming) {
            // Streamed responses carry the rows and the stats trailer only: 'stats', 'explain' and 'explainPlan'
            // below are properties of the buffered envelope, which no longer exists here. A caller that wants
            // them asks for the buffered encoding, where nothing changed.
            outcome = streamResultSetAsNdJson(exchange, database, serializer, limit, maxResultRows, qResult,
                includeTypeHints);
            profile.addSerializationNanos(System.nanoTime() - serializationStart);
            logIfTruncatedByDefault(database.getName(), originalCommand, limit, requestLimit, planLimit, outcome);

            Metrics.counter("http.command").increment();
            recordProfilerMetrics("http.command", profile);
            recordServerProfile(database.getName(), language, command, profile, qResult);
            return null;
          }

          outcome = serializeResultSetBounded(database, serializer, limit, maxResultRows, response, qResult,
              includeTypeHints);

          if (qResult != null) {
            final var qStats = qResult.getStatistics();
            if (qStats.isPresent() && qStats.get().containsUpdates())
              response.put("stats", qStats.get().toJSON());
          }

          if (qResult != null && qResult.getExecutionPlan().isPresent() &&
              (profileExecution != null ||
                  command.regionMatches(true, 0, "PROFILE ", 0, 8))) {
            final var executionPlan = qResult.getExecutionPlan().get();
            response.put("explain", executionPlan.prettyPrint(0, 2));
            response.put("explainPlan", executionPlan.toResult().toJSON());
          }
          profile.addSerializationNanos(System.nanoTime() - serializationStart);
        }

        reportLimits(response, limit, outcome);
        logIfTruncatedByDefault(database.getName(), originalCommand, limit, requestLimit, planLimit, outcome);

        if (detailedProfile)
          response.put("profile", profile.toJSON());

        Metrics.counter("http.command").increment();
        recordProfilerMetrics("http.command", profile);

        recordServerProfile(database.getName(), language, command, profile, qResult);

        return new ExecutionResponse(200, response.toString());
      } finally {
        if (qResult != null)
          qResult.close();
      }
    }

    } finally {
      QueryProfile.popCurrent();
    }
  }

public Object deserializeValue(final Database database, final Binary deserialized, final byte type,
      final EmbeddedModifier embeddedModifier, final boolean applyEncryption) {
    final Binary content = applyEncryption && dataEncryption != null &&
        type != BinaryTypes.TYPE_NULL &&
        type != BinaryTypes.TYPE_COMPRESSED_RID &&
        type != BinaryTypes.TYPE_RID ? new Binary(dataEncryption.decrypt(deserialized.getBytes())) : deserialized;

    final Object value;
    switch (type) {
    case BinaryTypes.TYPE_NULL:
      value = null;
      break;
    case BinaryTypes.TYPE_STRING:
      // A string reads back as the string that was written, always. This used to sniff the first characters and return
      // a spatial4j Shape when they looked like the head of a WKT geometry, which broke the identity of a declared
      // STRING property and mangled any free text starting with POINT/POLYGON/... (issue #5600). Databases written
      // before 26.2.1 - where shapes were stored as WKT text under TYPE_STRING - keep working because every geometry
      // consumer accepts WKT: see GeoUtils.parseGeometry(), GeoUtils.parseJtsGeometry() and LSMTreeGeoIndex.toShape().
      value = content.getString();
      break;
    case BinaryTypes.TYPE_COMPRESSED_STRING:
      value = database.getSchema().getDictionary().getNameById((int) content.getUnsignedNumber());
      break;
    case BinaryTypes.TYPE_BINARY:
      value = content.getBytes();
      break;
    case BinaryTypes.TYPE_COMPRESSED_GEOMETRY:
      value = deserializeGeometryBinary(content);
      break;
    case BinaryTypes.TYPE_BYTE:
      value = content.getByte();
      break;
    case BinaryTypes.TYPE_BOOLEAN:
      value = content.getByte() == 1;
      break;
    case BinaryTypes.TYPE_SHORT:
      value = (short) content.getNumber();
      break;
    case BinaryTypes.TYPE_INT:
      value = (int) content.getNumber();
      break;
    case BinaryTypes.TYPE_LONG:
      value = content.getNumber();
      break;
    case BinaryTypes.TYPE_FLOAT:
      value = Float.intBitsToFloat((int) content.getNumber());
      break;
    case BinaryTypes.TYPE_DOUBLE:
      value = Double.longBitsToDouble(content.getNumber());
      break;
    case BinaryTypes.TYPE_DATE:
      value = DateUtils.date(database, content.getUnsignedNumber(), dateImplementation);
      break;
    case BinaryTypes.TYPE_DATETIME_SECOND:
      value = DateUtils.dateTime(database, content.getUnsignedNumber(), ChronoUnit.SECONDS, dateTimeImplementation,
          ChronoUnit.SECONDS);
      break;
    case BinaryTypes.TYPE_DATETIME:
      value = DateUtils.dateTime(database, content.getUnsignedNumber(), ChronoUnit.MILLIS, dateTimeImplementation,
          ChronoUnit.MILLIS);
      break;
    case BinaryTypes.TYPE_DATETIME_MICROS:
      value = DateUtils.dateTime(database, content.getUnsignedNumber(), ChronoUnit.MICROS, dateTimeImplementation,
          ChronoUnit.MICROS);
      break;
    case BinaryTypes.TYPE_DATETIME_NANOS:
      value = DateUtils.dateTime(database, content.getUnsignedNumber(), ChronoUnit.NANOS, dateTimeImplementation, ChronoUnit.NANOS);
      break;
    case BinaryTypes.TYPE_DECIMAL:
      final int scale = (int) content.getNumber();
      final byte[] unscaledValue = content.getBytes();
      value = new BigDecimal(new BigInteger(unscaledValue), scale);
      break;
    case BinaryTypes.TYPE_COMPRESSED_RID:
      value = RID.create(database, (int) deserialized.getNumber(), deserialized.getNumber());
      break;
    case BinaryTypes.TYPE_RID:
      value = RID.create(database, deserialized.getInt(), deserialized.getLong());
      break;
    case BinaryTypes.TYPE_UUID:
      value = new UUID(content.getNumber(), content.getNumber());
      break;
    case BinaryTypes.TYPE_LIST: {
      final int count = checkDeserializedCount(content.getUnsignedNumber(), content);
      final List<Object> list = new ArrayList<>(count);
      for (int i = 0; i < count; ++i) {
        final byte entryType = content.getByte();
        list.add(deserializeValue(database, content, entryType, embeddedModifier, applyEncryption));
      }
      value = list;
      break;
    }
    case BinaryTypes.TYPE_MAP: {
      final int count = checkDeserializedCount(content.getUnsignedNumber(), content);
      final Map<Object, Object> map = new LinkedHashMap<>(count);
      for (int i = 0; i < count; ++i) {
        final byte entryKeyType = content.getByte();
        final Object entryKey = deserializeValue(database, content, entryKeyType, embeddedModifier, applyEncryption);

        final byte entryValueType = content.getByte();
        final Object entryValue = deserializeValue(database, content, entryValueType, embeddedModifier, applyEncryption);

        map.put(entryKey, entryValue);
      }
      value = map;
      break;
    }
    case BinaryTypes.TYPE_EMBEDDED: {
      final String typeName = database.getSchema().getDictionary().getNameById((int) content.getUnsignedNumber());

      final int embeddedObjectSize = (int) content.getUnsignedNumber();

      final Binary embeddedBuffer = content.slice(content.position(), embeddedObjectSize);

      value = ((DatabaseInternal) database).getRecordFactory()
          .newImmutableRecord(database, database.getSchema().getType(typeName), null, embeddedBuffer, embeddedModifier);

      content.position(content.position() + embeddedObjectSize);
      break;
    }
    case BinaryTypes.TYPE_ARRAY_OF_SHORTS: {
      final int count = checkDeserializedCount(content.getUnsignedNumber(), content);
      final short[] array = new short[count];
      for (int i = 0; i < count; ++i)
        array[i] = (short) content.getNumber();
      value = array;
      break;
    }
    case BinaryTypes.TYPE_ARRAY_OF_INTEGERS: {
      final int count = checkDeserializedCount(content.getUnsignedNumber(), content);
      final int[] array = new int[count];
      for (int i = 0; i < count; ++i)
        array[i] = (int) content.getNumber();
      value = array;
      break;
    }
    case BinaryTypes.TYPE_ARRAY_OF_LONGS: {
      final int count = checkDeserializedCount(content.getUnsignedNumber(), content);
      final long[] array = new long[count];
      for (int i = 0; i < count; ++i)
        array[i] = content.getNumber();
      value = array;
      break;
    }
    case BinaryTypes.TYPE_ARRAY_OF_FLOATS: {
      final int count = checkDeserializedCount(content.getUnsignedNumber(), content);
      final float[] array = new float[count];
      for (int i = 0; i < count; ++i)
        array[i] = Float.intBitsToFloat((int) content.getNumber());
      value = array;
      break;
    }
    case BinaryTypes.TYPE_ARRAY_OF_DOUBLES: {
      final int count = checkDeserializedCount(content.getUnsignedNumber(), content);
      final double[] array = new double[count];
      for (int i = 0; i < count; ++i)
        array[i] = Double.longBitsToDouble(content.getNumber());
      value = array;
      break;
    }

    default:
      throw new SerializationException("Error on deserializing value of unknown type " + type);
    }
    return value;
  }

public Map<String, Object> checkEdges(final String typeName, final Collection<RID> scopedRecords,
      final boolean fix, final boolean deleteOrphans, final int verboseLevel, final int maxWarnings,
      final int maxCorrupted) {
    final AtomicLong autoFix = new AtomicLong();
    final AtomicLong missingReferenceBack = new AtomicLong();
    // The three #6090 counters below, and the two above, are AtomicLong for CAPTURE, not for concurrency. This
    // scan is strictly single-threaded - CheckReport says so on its own plain-long fields, and the sets beside
    // these are not thread-safe either - but they are incremented from inside the checkEndpoints lambda, and a
    // local a lambda mutates has to be a mutable box. CheckReport could drop its atomics precisely because they
    // became FIELDS of an object; these are locals of the method, so a box is what there is. Do not read them as
    // a claim that anything here runs in parallel.
    /** #6090: edge records reachable from NO adjacency list - the orphan count. Exact, never capped. */
    final AtomicLong unreachableEdgeRecords = new AtomicLong();
    /** #6090: edges absent from their OUT vertex's OUT list. A defect for every edge type. */
    final AtomicLong edgesMissingOutReference = new AtomicLong();
    /** #6090: BIDIRECTIONAL edges absent from their IN vertex's IN list. Not a defect for a unidirectional type. */
    final AtomicLong edgesMissingInReference = new AtomicLong();
    /**
     * #6090: the RIDs behind {@code unreachableEdgeRecords}, so an operator can answer "which ones?" without
     * re-deriving them from a full traversal. Bounded by the same cap as the corrupted set - the count beside it
     * stays exact.
     */
    final Set<RID> unreachableEdgeRecordsFound = new LinkedHashSet<>();
    // CheckReport keeps corruptedRecords as a Set (matching checkVertices) so the same RID flagged on both sides of
    // an edge is recorded once, and totalCorrupted - which counts only genuinely new entries, see
    // CollectionUtils.addBounded - stays aligned with its size.
    final CheckReport report = new CheckReport(maxWarnings, maxCorrupted, verboseLevel);
    final Map<RID, Long> missingReferences = new HashMap<>();
    final Map<RID, String> missingReferenceErrors = new HashMap<>();
    // Vertices whose edge LIST failed to walk during the back-reference probe: warned once each (a broken
    // super-node chain is referenced by millions of edges), never flagged corrupted - see the probe guards.
    final Set<RID> unreadableListVertices = new HashSet<>();
    /** Records this run actually removed, surfaced as {@code deletedRecordsAfterFix}. */
    final Set<RID> deletedRecords = new LinkedHashSet<>();
    /**
     * Answers "does this endpoint's list name the edge?" without re-walking the same list once per incident edge
     * (issue #6062). Safe for the whole scan: this pass writes nothing while it scans - the deletes happen in the
     * repair loop below, after the cache is dropped.
     */
    final AdjacencyProbeCache probeCache = new AdjacencyProbeCache(graphEngine, adjacencyCacheEntries);

    final Map<String, Object> stats = new HashMap<>();

    beginPass();
    boolean completed = false;

    try {
      // The endpoint check of ONE edge: shared by the type-wide scan and the RECORD-scoped enumeration.
      final Consumer<Record> checkEndpoints = record -> {
        progressTick();
        final RID edgeRID = record.getIdentity();

        try {
          final Edge edge = record.asEdge(true);

          if (edge == null) {
            report.warn("edge " + edgeRID + " cannot be loaded");
            report.corrupt(edgeRID);

          } else if (edge.getIn() == null || !edge.getIn().isValid()) {
            report.warn("edge " + edgeRID + " has an invalid incoming link " + edge.getIn());
            report.corrupt(edgeRID);
            ++report.invalidLinks;

          } else if (edge.getOut() == null || !edge.getOut().isValid()) {
            report.warn("edge " + edgeRID + " has an invalid outgoing link " + edge.getOut());
            report.corrupt(edgeRID);
            ++report.invalidLinks;

          } else {
            // #6090: the two probes below record WHAT THEY ESTABLISHED, not just that something was missing.
            // "Probed" means the far vertex loaded and its list was walked to a conclusion; only then may the
            // absence be believed. See the class-level note on why that distinction is load-bearing here.
            boolean outProbed = false;
            boolean outUnreferenced = false;
            boolean inProbed = false;
            boolean inUnreferenced = false;

            // #5777: BOTH endpoints go through the same arm, so the two sides cannot report the same finding
            // differently again. This one used to flag the missing IN vertex corrupted where the OUT arm below
            // flagged only the edge - see loadEndpointVertex for which of the two was right and why.
            final VertexInternal inVertex = loadEndpointVertex(edge, edgeRID, Vertex.DIRECTION.IN, report,
                missingReferences, missingReferenceErrors);

            if (inVertex != null)
              try {
                // Memoised per list (#6062). A vertex with no IN list at all answers false, exactly as the
                // inEdges == null arm this replaces did, and an unreadable one still throws into the guard below.
                final boolean referenced = probeCache.containsEdge(inVertex, Vertex.DIRECTION.IN, edgeRID);
                inProbed = true;
                if (!referenced) {
                  // LEGITIMATE FOR A UNIDIRECTIONAL EDGE TYPE, a defect for a bidirectional one - which is why the
                  // raw counter below cannot be read as a defect count and #6090 added ones that can. Bumped here
                  // unconditionally, exactly as before, so its published meaning does not shift under existing
                  // readers; the classification happens once both sides have answered.
                  missingReferenceBack.incrementAndGet();
                  inUnreferenced = true;
                }
              } catch (final Exception e) {
                // The vertex record is FINE but its edge LIST is unreadable: neither the edge nor the vertex is
                // at fault, so NOTHING is flagged corrupted here (before this guard the vertex was deleted by
                // fix mode over its broken chain). checkVertices runs after this phase and rebuilds the list
                // from the surviving edge records.
                if (unreadableListVertices.add(inVertex.getIdentity()))
                  report.warn("vertex " + inVertex.getIdentity() + " incoming edge list is unreadable (error: " + describe(e)
                          + "), left to the vertex check to rebuild");
              }

            final VertexInternal outVertex = loadEndpointVertex(edge, edgeRID, Vertex.DIRECTION.OUT, report,
                missingReferences, missingReferenceErrors);

            if (outVertex != null)
              try {
                // See the incoming side: memoised per list rather than re-walked per edge (#6062).
                final boolean referenced = probeCache.containsEdge(outVertex, Vertex.DIRECTION.OUT, edgeRID);
                outProbed = true;
                if (!referenced) {
                  // ALWAYS A DEFECT, for every edge type: no outgoing traversal can reach the record. Same
                  // unconditional bump of the legacy counter as the incoming side, for the same reason.
                  missingReferenceBack.incrementAndGet();
                  outUnreferenced = true;
                }
              } catch (final Exception e) {
                // Same as the incoming side: an unreadable LIST is not a corrupted edge or vertex.
                if (unreadableListVertices.add(outVertex.getIdentity()))
                  report.warn("vertex " + outVertex.getIdentity() + " outgoing edge list is unreadable (error: " + describe(e)
                          + "), left to the vertex check to rebuild");
              }

            // #6090: classify what the two probes established, and report it.
            if (outProbed && outUnreferenced) {
              edgesMissingOutReference.incrementAndGet();

              // UNREACHABLE means BOTH lists were walked and neither names the record - required even for a
              // unidirectional type, whose IN list is not expected to name the edge at all. NOT because the flag
              // can be flipped under us: LocalEdgeType.bidirectional is final, unlike lightweight/unique, so
              // ALTER TYPE cannot change it. It is because "no list references this record" is the claim the
              // deletion rests on, and only a walk can establish it - a type dropped and recreated over the same
              // data, or an entry an older build left in an IN list, both make the record reachable while the
              // schema says it should not be. Costs one probe that already ran for missingReferenceBack anyway.
              if (inProbed && inUnreferenced) {
                unreachableEdgeRecords.incrementAndGet();
                CollectionUtils.addBounded(unreachableEdgeRecordsFound, maxCorrupted, edgeRID);
                report.warn("edge " + edgeRID + " is an ORPHAN RECORD: the outgoing vertex " + edge.getOut()
                    + " does not reference it from its OUT list" + (isBidirectional(edge) ?
                    " and neither does the incoming vertex " + edge.getIn() + " from its IN list" :
                    ", and the type is unidirectional so the incoming vertex " + edge.getIn() + " holds no reference "
                        + "either") + ", so no traversal reaches it"
                    + (fix && deleteOrphans ? ", removing it" : " (run CHECK DATABASE FIX DELETE ORPHANS to reclaim it)"));
                if (fix && deleteOrphans)
                  // Flagged corrupted ONLY under the explicit opt-in: that is what hands the RID to the repair
                  // loop below AND puts its bucket into the caller's affectedBuckets, so the raw bucket delete
                  // used there does not leave the edge type's indexes pointing at a record that is gone.
                  report.corrupt(edgeRID);
              } else
                // DELIBERATELY NOT SUPPRESSED for an edge the endpoint checks above already flagged corrupted (a
                // dangling link whose OUT list happens not to name it either): the two findings are different -
                // "its target is gone" and "its source does not list it" - and the second is what tells an
                // operator the adjacency is damaged too, rather than only the far end. Reachable only when both
                // hold, so it is not a warning per dangling edge.
                report.warn("edge " + edgeRID + " is not referenced back by its outgoing vertex " + edge.getOut()
                    + ": it is missing from that vertex's OUT list");
            }

            // A bidirectional edge absent from its target's IN list is a defect even when the OUT side is intact -
            // an incoming traversal misses it. Reported apart from the orphan case, which already named both sides.
            if (inProbed && inUnreferenced && isBidirectional(edge)) {
              edgesMissingInReference.incrementAndGet();
              if (!(outProbed && outUnreferenced))
                report.warn("edge " + edgeRID + " is not referenced back by its incoming vertex " + edge.getIn()
                    + ": it is missing from that vertex's IN list");
            }
          }

        } catch (final Throwable e) {
          report.warn("edge " + record.getIdentity() + " cannot be loaded (error: " + describe(e) + ")");
          report.corrupt(edgeRID);
        }
      };

      if (scopedRecords != null) {
        progressBegin(progressStepName, scopedRecords.size());

        for (final RID rid : scopedRecords) {
          try {
            checkEndpoints.accept(database.lookupByRID(rid, true));
          } catch (final RecordNotFoundException e) {
            // See the vertex arm: a missing RID is reported, never flagged corrupted, so FIX does not rebuild
            // this bucket's indexes over what is usually just a stale or mistyped RID.
            progressTick();
            report.warn("edge " + rid + " does not exist");
          } catch (final Exception e) {
            // See the vertex arm, including what that guard does and does not cover.
            progressTick();
            report.warn("edge " + rid + " cannot be loaded (error: " + describe(e) + ")");
            report.corrupt(rid);
          }
        }
      } else {
        // ONE FULL PASS OVER THE TYPE (#5773): progress total is the record count. See checkVertices for why the
        // record-type scan that used to precede this detected nothing the endpoint pass misses.
        progressBegin(progressStepName, database.countType(typeName, false));

        database.scanType(typeName, false, record -> {
          checkEndpoints.accept(record);
          return true;
        }, (rid, exception) -> {
          progressTick();
          report.warn("edge " + rid + " cannot be loaded (error: " + describe(exception) + ")");
          report.corrupt(rid);
          return true;
        });
      }

      progressComplete();

      // NOTHING PROBES AFTER THIS POINT and the repair loop deletes records: drop the images (#6062).
      probeCache.clear();

      if (fix) {
        for (final RID rid : report.corruptedRecords) {
          if (rid == null)
            continue;

          try {
            deleteCorruptedRecord(rid);
            // Counted AFTER the delete returns, not before it is attempted (issue #6128). autoFix is what an
            // operator reads to decide whether a run did anything, so it must not include a repair that failed -
            // and the failure here is routine rather than exotic. It used to be so by construction: a dangling
            // edge flagged its ABSENT endpoint alongside itself, whose delete could never succeed, so one
            // dangling edge reported two repairs. #5777 stopped flagging an endpoint that is merely not there,
            // and what remains is the ordinary race - the record this pass read and flagged is gone by the time
            // the repair loop reaches it.
            autoFix.incrementAndGet();
            // Reported, not only counted: an operator reads deletedRecordsAfterFix to learn WHICH records a repair
            // removed, and until this arm populated it the answer depended on which pass happened to do the delete -
            // a broken-chain record was listed (LocalBucket.check removed it) and every other corrupt record was not.
            // Bounded by the same cap as report.corruptedRecords, which this iterates.
            deletedRecords.add(rid);
          } catch (final RecordNotFoundException e) {
            // IGNORE IT
          } catch (final Throwable e) {
            report.warn("Cannot fix the record " + rid + ": error on delete (error: " + e.getMessage() + ")");
          }
          commitRepairBatchIfFull();
        }
      }

      if (verboseLevel > 0)
        for (final String warning : report.warnings)
          LogManager.instance().log(this, Level.WARNING, "- " + warning);

      completed = true;

    } finally {
      // Same sum as the vertex arm, and prunedDanglingEntries is structurally ZERO here: pruning happens in
      // checkIncomingEdges/checkOutgoingEdges, which only checkVertices calls. Kept rather than simplified to
      // autoFix.get() so the two arms report autoFix identically, and so an edge arm that one day does prune -
      // #5777 changed exactly this arm's handling of endpoints - cannot silently stop counting it. Do not read
      // it as evidence that this arm prunes today. reconnectedEdges is structurally zero here for the same reason:
      // this arm plans no re-links.
      putRepairCounters(stats, autoFix.get(), report.prunedDanglingEntries, 0L);
      putProbeCounters(stats, probeCache);
      stats.put("deletedRecordsAfterFix", deletedRecords);
      stats.put("corruptedRecords", report.corruptedRecords);
      stats.put("invalidLinks", report.invalidLinks);
      stats.put("missingReferenceBack", missingReferenceBack.get());
      // #6090: the readable form of the counter above - see the method Javadoc for what each one means.
      stats.put("unreachableEdgeRecords", unreachableEdgeRecords.get());
      stats.put("edgesMissingOutReference", edgesMissingOutReference.get());
      stats.put("edgesMissingInReference", edgesMissingInReference.get());
      stats.put("unreachableEdgeRecordsFound", unreachableEdgeRecordsFound);
      stats.put("warnings", report.warnings);
      stats.put("totalWarnings", report.totalWarnings);
      stats.put("totalCorruptedRecords", report.totalCorrupted);
      stats.put("missingReferences", missingReferences);
      stats.put("missingReferenceErrors", missingReferenceErrors);
      finishPass(completed);
    }

    return stats;
  }

